    #[test]
    fn v2_knn_search_recall_matches_brute_force() {
        // Round-trip, end to end: write a segment with several vectors
        // under the v2 (posting-based) writer default, reopen it, run a
        // real `query.knn` search through `Searcher::search`, and confirm
        // the results actually match brute-force nearest neighbors over the
        // same vectors — not just "returns something without erroring".
        let dir = std::env::temp_dir().join("kosha-test-knn-v2-recall");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);

        let mut vectors: Vec<(String, Vec<f32>)> = Vec::new();
        for i in 0..40u32 {
            let angle = (i as f32) * std::f32::consts::PI / 20.0;
            let v = vec![angle.cos(), angle.sin(), 0.0, 0.0];
            let doc_id = format!("d{i}");
            w.add_document(
                DocumentId(doc_id.clone()),
                vec![Field::vector("contentEmbedding", v.clone())],
            );
            vectors.push((doc_id, v));
        }
        w.finalize(Bm25Params::default()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 40,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());

        let query_vector = vec![1.0, 0.0, 0.0, 0.0]; // exact match for d0 (angle 0)
        let mut q = mk_query("", 5);
        q.knn = Some(kosha_core::KnnQuery {
            query_text: None,
            embedding_model: None,
            field: "contentEmbedding".into(),
            vector: query_vector.clone(),
            k: 5,
            num_candidates: 40, // probe ~everything, this test is about recall not nprobe tuning
            filter: None,
            vectors: None,
            scoring: None,
        });
        let r = searcher.search(&ns, &manifest, &q, None).unwrap();
        assert_eq!(r.results.len(), 5);

        // Brute-force ground truth over the exact same vectors, cosine similarity.
        let mut brute: Vec<(String, f32)> = vectors
            .iter()
            .map(|(id, v)| {
                let dot: f32 = v.iter().zip(&query_vector).map(|(a, b)| a * b).sum();
                let norm_v: f32 = v.iter().map(|x| x * x).sum::<f32>().sqrt();
                let norm_q: f32 = query_vector.iter().map(|x| x * x).sum::<f32>().sqrt();
                (id.clone(), dot / (norm_v * norm_q))
            })
            .collect();
        brute.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        let expected_top5: Vec<String> = brute.iter().take(5).map(|(id, _)| id.clone()).collect();

        let got_ids: Vec<String> = r.results.iter().map(|hit| hit.doc_id.0.clone()).collect();
        let overlap = got_ids
            .iter()
            .filter(|id| expected_top5.contains(id))
            .count();
        assert!(
            overlap >= 4,
            "expected at least 4/5 recall against brute force, got {overlap}/5 \
             (got={got_ids:?}, expected={expected_top5:?})"
        );
        // The exact match at the query vector must always be found.
        assert!(
            got_ids.contains(&"d0".to_string()),
            "exact match must always be in the results: {got_ids:?}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn thin_global_budget_can_bury_the_true_neighbour_in_a_diluted_centroid() {
        // The real 10M-doc/~200-segment run measured mean recall@10 of
        // 0.563 (some queries at 0.0) at num_candidates=100 — the
        // "tpuf-comparable" default every existing recall test runs well
        // above (knn_global_budget_preserves_top_hit_against_brute_force
        // uses 8 segments at num_candidates=32, a 4x-over-segment-count
        // ratio; the real run's ratio was ~0.5x). `knn_plan`
        // provably preserves the true global top-`num_candidates`
        // *centroids* (per-segment truncation can't drop a true top-K
        // member — proved by construction, not just tested here) — so the
        // failure isn't there. It's the next step down: probing only
        // selects which *clusters* get hydrated, and a cluster's centroid
        // is an average of its members. A cluster whose centroid is
        // mediocre because its OTHER members happen to sit far from the
        // query can lose the global cutoff entirely, even while burying an
        // individual document that would have been the single best answer
        // in the whole corpus — classic IVF quantization error.
        //
        // This exact corpus originally proved the target excluded at ANY
        // budget up to 50 (dead last, rank 51/51, under raw centroid
        // distance) — the finding that motivated radius-aware ranking
        // (`RADIUS_AWARE_VECTOR_INDEX_VERSION`, now the default write
        // format: see `radius_aware_ranking_finds_the_diluted_neighbour_without_widening_the_budget`,
        // the sibling test proving that fix resolves this SAME corpus at
        // num_candidates=15). Radius-awareness is now on by default here
        // too, which is real progress — the target's effective rank moves
        // from dead last (51/51) to 10th of 51 — but a lower bound is
        // still a bound, not a promise of finding everything on zero
        // budget: this test now shows an even thinner budget (5, clear of
        // the target's rank-10 lower bound with margin) still excludes it.
        // The mechanism helps; it doesn't make budget irrelevant.
        //
        // Constructed deterministically, not relying on realistic-looking
        // random data: one "target" segment holds the true nearest
        // neighbour (8° from the query, cos_sim ~0.99) paired with a
        // deliberately opposite "diluter" doc (170°) — their average
        // centroid lands at ~89°, cos_sim ~0.017, nearly orthogonal to the
        // query. 50 one-doc "decoy" segments sit at 20°-80°, all with
        // cos_sim strictly greater than the target centroid's ~0.017 (by
        // construction, verified below), so a "closest centroid first"
        // global ranking always ranks every decoy ahead of the target on
        // raw distance.
        let dir = std::env::temp_dir().join("kosha-test-knn-thin-budget-dilution");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());

        let unit = |deg: f32| {
            let r = deg.to_radians();
            vec![r.cos(), r.sin()]
        };

        let mut entries = Vec::new();

        // Target segment: the true nearest neighbour, diluted by an
        // opposite-facing doc in the same (tiny, sub-min_posting_size)
        // segment so SPFresh forms exactly one centroid = their average.
        let target_dir = dir.join(&ns.0).join("target");
        let mut tw = SegmentWriter::new(SegmentId("target".into()), target_dir);
        tw.add_document(
            DocumentId("true-nn".into()),
            vec![Field::vector("emb", unit(8.0))],
        );
        tw.add_document(
            DocumentId("diluter".into()),
            vec![Field::vector("emb", unit(170.0))],
        );
        tw.finalize(Bm25Params::default()).unwrap();
        entries.push(ManifestEntry {
            segment_id: SegmentId("target".into()),
            doc_count: 2,
        });

        // Verify the dilution math holds before trusting the rest of the
        // test on it: the target centroid's cosine similarity to the query
        // must be lower than every decoy's.
        let q = unit(0.0);
        let cos_sim = |a: &[f32], b: &[f32]| -> f32 {
            let dot: f32 = a.iter().zip(b).map(|(x, y)| x * y).sum();
            let na: f32 = a.iter().map(|x| x * x).sum::<f32>().sqrt();
            let nb: f32 = b.iter().map(|x| x * x).sum::<f32>().sqrt();
            dot / (na * nb)
        };
        let mut centroid = vec![0.0f32; 2];
        for v in [unit(8.0), unit(170.0)] {
            for (c, x) in centroid.iter_mut().zip(&v) {
                *c += x;
            }
        }
        let target_centroid_sim = cos_sim(&q, &centroid);

        const DECOYS: usize = 50;
        for i in 0..DECOYS {
            let deg = 20.0 + (i as f32) * (60.0 / (DECOYS as f32 - 1.0)); // 20°..80°
            let decoy_sim = cos_sim(&q, &unit(deg));
            assert!(
                decoy_sim > target_centroid_sim,
                "decoy {i} at {deg}° (cos_sim={decoy_sim}) must beat the target \
                 centroid (cos_sim={target_centroid_sim}) for this test to be valid"
            );
            let seg = format!("decoy{i:03}");
            let seg_dir = dir.join(&ns.0).join(&seg);
            let mut w = SegmentWriter::new(SegmentId(seg.clone()), seg_dir);
            w.add_document(
                DocumentId(format!("{seg}-d0")),
                vec![Field::vector("emb", unit(deg))],
            );
            w.finalize(Bm25Params::default()).unwrap();
            entries.push(ManifestEntry {
                segment_id: SegmentId(seg),
                doc_count: 1,
            });
        }

        let total_segments = entries.len(); // 51
        let manifest = Manifest {
            version: 1,
            segments: entries,
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let mk_knn_q = |num_candidates: usize| {
            let mut q = mk_query("", 1);
            q.knn = Some(kosha_core::KnnQuery {
                query_text: None,
                embedding_model: None,
                field: "emb".into(),
                vector: unit(0.0),
                k: 1,
                num_candidates,
                filter: None,
                vectors: None,
                scoring: None,
            });
            q
        };

        // Thin budget (well under the target's radius-aware rank of 10):
        // the target segment's lower bound still loses the global cutoff,
        // so the buried true nearest neighbour is never even hydrated —
        // zero recall on this query, not a near-miss. This is the failure
        // mode the real benchmark hit (some queries measured
        // recall_at_k == 0.0) — radius-awareness narrows when it happens,
        // it doesn't eliminate the need for an adequate budget.
        let thin = searcher.search(&ns, &manifest, &mk_knn_q(5), None).unwrap();
        assert!(
            !thin.results.is_empty(),
            "the budget excludes the target segment, not every segment — a \
             decoy must still answer"
        );
        assert_ne!(
            thin.results.first().map(|h| h.doc_id.0.clone()),
            Some("true-nn".to_string()),
            "at num_candidates=5 (well clear of the target's radius-aware \
             rank of 10 among {}), the true nearest neighbour must still be \
             excluded — got {:?}",
            DECOYS + 1,
            thin.results
        );

        // Generous budget (>= total segment count): knn_plan's
        // own short-circuit admits every segment, the target's centroid
        // now qualifies, and the buried true neighbour — by far the
        // single closest individual document in the corpus — is found.
        let generous = searcher
            .search(&ns, &manifest, &mk_knn_q(total_segments), None)
            .unwrap();
        assert_eq!(
            generous.results.first().map(|h| h.doc_id.0.clone()),
            Some("true-nn".to_string()),
            "at num_candidates >= segment count every centroid qualifies — the \
             true nearest neighbour must be found: {:?}",
            generous.results
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A namespace of 300-vector segments, one per entry of `formats`, for
    /// the global rescoring tests (#381): `(dir, ns, manifest, corpus)`
    /// with `corpus` every `(doc_id, vector)`.
    fn global_rescore_corpus(
        name: &str,
        formats: &[kosha_core::VectorQuantization],
    ) -> (
        std::path::PathBuf,
        NamespaceId,
        Manifest,
        Vec<(String, Vec<f32>)>,
    ) {
        let dir = std::env::temp_dir().join(format!(
            "kosha-test-knn-global-rescore-{name}-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let mut entries = Vec::new();
        let mut corpus = Vec::new();
        for (seg_idx, &quantization) in formats.iter().enumerate() {
            let seg = format!("seg{seg_idx}-{}", quantization.as_str());
            let mut w = SegmentWriter::new(SegmentId(seg.clone()), dir.join(&ns.0).join(&seg))
                .with_vector_quantization(kosha_segment::VectorQuantizationConfig::all(
                    quantization,
                ));
            for i in 0..300u64 {
                let id = format!("{seg}-{i}");
                let v = global_rescore_vector(seg_idx as u64 * 1000 + i);
                corpus.push((id.clone(), v.clone()));
                w.add_document(DocumentId(id), vec![Field::vector("emb", v)]);
            }
            w.finalize(Bm25Params::default()).unwrap();
            entries.push(ManifestEntry {
                segment_id: SegmentId(seg),
                doc_count: 300,
            });
        }
        let manifest = Manifest {
            version: 1,
            segments: entries,
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            schema: None,
            retired: Default::default(),
            shards: None,
            branch: None,
        };
        (dir, ns, manifest, corpus)
    }

    fn global_rescore_vector(seed: u64) -> Vec<f32> {
        let mut state = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
        (0..32)
            .map(|_| {
                state ^= state << 13;
                state ^= state >> 7;
                state ^= state << 17;
                (state >> 40) as f32 / (1u64 << 23) as f32 - 1.0
            })
            .collect()
    }

    fn global_rescore_query(vector: Vec<f32>, k: usize) -> SearchQuery {
        let mut q = mk_query("", k);
        q.knn = Some(kosha_core::KnnQuery {
            query_text: None,
            embedding_model: None,
            field: "emb".into(),
            vector,
            k,
            // Every posting of every segment: only quantization, not the
            // probe budget, could cost recall.
            num_candidates: 10_000,
            filter: None,
            scoring: None,
            vectors: None,
        });
        q
    }

    /// The brute-force f32 top `k` of `corpus` for `query`: `(id, cosine)`.
    fn global_rescore_brute_force(
        corpus: &[(String, Vec<f32>)],
        query: &[f32],
        k: usize,
    ) -> Vec<(String, f64)> {
        let cosine = |a: &[f32], b: &[f32]| -> f64 {
            let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
            let na: f64 = a.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            let nb: f64 = b.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            dot / (na * nb)
        };
        let mut exact: Vec<(String, f64)> = corpus
            .iter()
            .map(|(id, v)| (id.clone(), cosine(query, v)))
            .collect();
        exact.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        exact.truncate(k);
        exact
    }

    #[test]
    fn knn_global_rescore_is_exact_against_f32_brute_force_with_i8_segments() {
        // #381: with global bound-driven rescoring, i8 segments (whose
        // strict bound is a guarantee) mixed with f32 ones return exactly
        // the f32 brute-force top k, scores included, and rescore only the
        // candidates the global k-th lower bound cannot rule out.
        use kosha_core::VectorQuantization::{F32, I8};
        let (dir, ns, manifest, corpus) = global_rescore_corpus("i8", &[F32, I8, I8, F32, I8, I8]);
        let global = Searcher::new(dir.clone()).with_knn_global_rescore(true);
        let default = Searcher::new(dir.clone())
            .with_knn_global_rescore(false)
            .with_knn_rescore_stats(false);
        let k = 10;
        for q_seed in 0..10u64 {
            let query = global_rescore_vector(900_000 + q_seed);
            let q = global_rescore_query(query.clone(), k);
            let (r, stats) = global.search_with_stats(&ns, &manifest, &q, None).unwrap();
            assert!(stats.knn_global_rescore);
            assert_eq!(r.knn_degraded_segments, Some(0));
            assert_eq!(stats.knn_rescore_unavailable, 0);
            assert!(stats.knn_rescored > 0);
            assert_eq!(stats.knn_rescored, stats.knn_rescore_selected);
            assert!(stats.knn_rescore_selected <= stats.knn_rescore_candidates);
            let want = global_rescore_brute_force(&corpus, &query, k);
            let got: Vec<&str> = r.results.iter().map(|h| h.doc_id.0.as_str()).collect();
            let want_ids: Vec<&str> = want.iter().map(|(id, _)| id.as_str()).collect();
            assert_eq!(got, want_ids, "query {q_seed}");
            // Pure kNN scores are `(cosine + 1) * 10`.
            for (hit, (_, cosine)) in r.results.iter().zip(&want) {
                assert!((hit.score - (cosine + 1.0) * 10.0).abs() < 1e-3);
            }

            // Off (the default), nothing about the query changes.
            let (_, off) = default.search_with_stats(&ns, &manifest, &q, None).unwrap();
            assert!(!off.knn_global_rescore);
            assert_eq!(off.knn_rescore_candidates, 0);
            assert_eq!(off.knn_rescored, 0);
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_per_segment_rescore_stats_count_exact_shortlist_scores() {
        use kosha_core::VectorQuantization::{F32, I8};

        let (dir, ns, manifest, _) = global_rescore_corpus("per-segment-stats", &[I8, I8, F32]);
        let q = global_rescore_query(global_rescore_vector(900_000), 10);
        let search = |enabled| {
            Searcher::new(dir.clone())
                .with_knn_global_rescore(false)
                .with_knn_rescore_stats(enabled)
                .search_with_stats(&ns, &manifest, &q, None)
                .unwrap()
        };
        let (_, disabled) = search(false);
        assert!(!disabled.knn_rescore_stats);
        assert_eq!(disabled.knn_rescored, 0);

        let (_, local) = search(true);
        let per_segment = (10 * kosha_segment::vector_rescore_factor()).min(300);
        assert!(local.knn_rescore_stats);
        assert_eq!(local.knn_seg_quantized, 2);
        assert_eq!(local.knn_rescored, 2 * per_segment);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_global_rescore_max_caps_the_exact_vector_reads() {
        // The cap bounds how many quantized candidates are rescored; with
        // no cap, or one above the selected count, nothing changes.
        use kosha_core::VectorQuantization::{RaBitQ, F32};
        let (dir, ns, manifest, _) = global_rescore_corpus("cap", &[RaBitQ, F32, RaBitQ, RaBitQ]);
        let uncapped = Searcher::new(dir.clone())
            .with_knn_global_rescore(true)
            .with_knn_global_rescore_max(None);
        let q = global_rescore_query(global_rescore_vector(700_001), 10);
        let (full, full_stats) = uncapped
            .search_with_stats(&ns, &manifest, &q, None)
            .unwrap();
        assert!(full_stats.knn_rescore_selected > 20, "fixture too easy");
        let cap = 20;
        let capped = Searcher::new(dir.clone())
            .with_knn_global_rescore(true)
            .with_knn_global_rescore_max(Some(cap));
        let (r, stats) = capped.search_with_stats(&ns, &manifest, &q, None).unwrap();
        assert!(
            stats.knn_rescore_selected <= cap,
            "{}",
            stats.knn_rescore_selected
        );
        assert_eq!(stats.knn_rescored, stats.knn_rescore_selected);
        assert_eq!(r.results.len(), full.results.len());
        let loose = Searcher::new(dir.clone())
            .with_knn_global_rescore(true)
            .with_knn_global_rescore_max(Some(full_stats.knn_rescore_selected));
        let (same, same_stats) = loose.search_with_stats(&ns, &manifest, &q, None).unwrap();
        assert_eq!(
            same_stats.knn_rescore_selected,
            full_stats.knn_rescore_selected
        );
        let ids = |r: &SearchResult| {
            r.results
                .iter()
                .map(|h| h.doc_id.0.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(ids(&same), ids(&full));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_global_rescore_recalls_the_f32_top_k_with_rabitq_segments() {
        use kosha_core::VectorQuantization::{RaBitQ, F32, I8};
        let (dir, ns, manifest, corpus) =
            global_rescore_corpus("rabitq", &[RaBitQ, F32, RaBitQ, I8, RaBitQ]);
        let searcher = Searcher::new(dir.clone()).with_knn_global_rescore(true);
        let (k, queries) = (10, 20u64);
        let mut recall = 0.0f64;
        for q_seed in 0..queries {
            let query = global_rescore_vector(800_000 + q_seed);
            let q = global_rescore_query(query.clone(), k);
            let (r, stats) = searcher
                .search_with_stats(&ns, &manifest, &q, None)
                .unwrap();
            assert!(stats.knn_global_rescore);
            assert_eq!(r.knn_degraded_segments, Some(0));
            let want: HashSet<String> = global_rescore_brute_force(&corpus, &query, k)
                .into_iter()
                .map(|(id, _)| id)
                .collect();
            recall += r
                .results
                .iter()
                .filter(|h| want.contains(&h.doc_id.0))
                .count() as f64
                / k as f64;
            assert!(r.results.windows(2).all(|w| w[0].score >= w[1].score));
        }
        let recall = recall / queries as f64;
        assert!(recall >= 0.95, "recall@10 {recall}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_global_rescore_reports_missing_exact_vectors_as_degraded() {
        // #381: the default path returns a quantized segment's estimates as
        // final when `doc_vectors.bin` is not local, with no signal. Global
        // rescoring keeps the estimates too (there is nothing better), but
        // counts the segment in `knn_degraded_segments` and the candidates
        // in `knn_rescore_unavailable`.
        use kosha_core::VectorQuantization::{F32, I8};
        let (dir, ns, manifest, _) = global_rescore_corpus("degraded", &[F32, I8, I8]);
        let sidecars: Vec<(PathBuf, Vec<u8>)> = manifest
            .segments
            .iter()
            .filter(|entry| entry.segment_id.0.contains("-i8"))
            .map(|entry| {
                let path = manifest
                    .segment_dir(&dir, &ns, &entry.segment_id)
                    .join(kosha_segment::DOC_VECTORS_FILE);
                let bytes = std::fs::read(&path).unwrap();
                (path, bytes)
            })
            .collect();
        let evict = || {
            for (path, _) in &sidecars {
                let _ = std::fs::remove_file(path);
            }
        };
        // Scoring sees no sidecar; the page's documents then get theirs
        // back, as the server's page hydrator would fetch them.
        let restore = |_: &[PageSegment<'_>]| {
            for (path, bytes) in &sidecars {
                std::fs::write(path, bytes).unwrap();
            }
        };
        let q = global_rescore_query(global_rescore_vector(4242), 10);

        evict();
        let (silent, silent_stats) = Searcher::new(dir.clone())
            .with_knn_global_rescore(false)
            .with_knn_rescore_stats(true)
            .search_with_hydrators(&ns, &manifest, &q, None, Some(&restore), None)
            .unwrap();
        assert_eq!(
            silent.knn_degraded_segments,
            Some(0),
            "today's per-segment path: estimates returned silently"
        );
        assert!(!silent_stats.knn_global_rescore);
        assert!(silent_stats.knn_rescore_stats);
        assert_eq!(silent_stats.knn_seg_unrescored, 2);
        assert_eq!(silent_stats.knn_rescored, 0);

        evict();
        let (r, stats) = Searcher::new(dir.clone())
            .with_knn_global_rescore(true)
            .search_with_hydrators(&ns, &manifest, &q, None, Some(&restore), None)
            .unwrap();
        assert!(stats.knn_global_rescore);
        assert!(stats.knn_rescore_unavailable > 0);
        assert_eq!(stats.knn_rescored, 0);
        assert_eq!(
            r.knn_degraded_segments,
            Some(2),
            "both i8 segments surface their unreadable exact vectors"
        );
        assert_eq!(r.results.len(), 10, "estimates still answer the query");
        // No candidate was lost (each kept its estimate), so this stays a
        // degraded 200, not a failure.
        assert!(stats.knn_failed_segments.is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_global_rescore_reads_exact_vectors_by_range_when_not_local() {
        // #381: codes-only local tier. `doc_vectors.bin` is not local, only
        // its header (as page materialization caches it); the exact vectors
        // the bound selects are fetched by ranged read through the search's
        // vector fetcher, once per query, and the answer is exact.
        use kosha_core::VectorQuantization::I8;
        let (dir, ns, manifest, corpus) = global_rescore_corpus("ranged", &[I8, I8]);
        let mut sidecars: HashMap<PathBuf, Vec<u8>> = HashMap::new();
        for entry in &manifest.segments {
            let seg_dir = manifest.segment_dir(&dir, &ns, &entry.segment_id);
            let path = seg_dir.join(kosha_segment::DOC_VECTORS_FILE);
            let bytes = std::fs::read(&path).unwrap();
            std::fs::remove_file(&path).unwrap();
            let header_len = kosha_segment::doc_vectors_header_len(&bytes)
                .unwrap()
                .unwrap();
            let spans =
                kosha_segment::span_cache::spans_dir(&seg_dir, kosha_segment::DOC_VECTORS_FILE);
            std::fs::create_dir_all(&spans).unwrap();
            std::fs::write(
                spans.join(kosha_segment::span_cache::span_file_name(0, header_len)),
                &bytes[..header_len as usize],
            )
            .unwrap();
            sidecars.insert(seg_dir, bytes);
        }
        let calls = Mutex::new(0usize);
        let fetch = |seg: &Path, file: &str, ranges: &[(u64, u64)]| {
            if file != kosha_segment::DOC_VECTORS_FILE {
                return kosha_segment::span_cache::SpanHolds::new();
            }
            *calls.lock().unwrap() += 1;
            let bytes = &sidecars[seg];
            let spans = kosha_segment::span_cache::spans_dir(seg, file);
            for &(s, e) in ranges {
                std::fs::write(
                    spans.join(kosha_segment::span_cache::span_file_name(s, e)),
                    &bytes[s as usize..e as usize],
                )
                .unwrap();
            }
            kosha_segment::span_cache::SpanHolds::new()
        };
        let searcher = Searcher::new(dir.clone()).with_knn_global_rescore(true);
        let query = global_rescore_vector(5150);
        let q = global_rescore_query(query.clone(), 10);
        let (r, stats) = searcher
            .search_with_hydrators(&ns, &manifest, &q, None, None, Some(&fetch))
            .unwrap();
        assert_eq!(r.knn_degraded_segments, Some(0));
        assert_eq!(stats.knn_rescore_unavailable, 0);
        assert!(stats.knn_rescore_ranged_spans > 0);
        assert_eq!(stats.knn_rescored, stats.knn_rescore_selected);
        assert!(*calls.lock().unwrap() >= 1);
        let want: Vec<String> = global_rescore_brute_force(&corpus, &query, 10)
            .into_iter()
            .map(|(id, _)| id)
            .collect();
        let got: Vec<String> = r.results.iter().map(|h| h.doc_id.0.clone()).collect();
        assert_eq!(got, want);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn namespace_mixing_f32_and_i8_segments_ranks_like_f32_brute_force() {
        // #210: an i8-quantized segment written next to f32 segments (a
        // namespace mid-migration) must rank as if every vector were f32:
        // the i8 segment rescores its shortlist from `doc_vectors.bin`, so
        // scores from both formats are the same exact cosine and merge
        // into one correct order.
        let dir = std::env::temp_dir().join(format!(
            "kosha-test-knn-mixed-quantization-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        const DIM: usize = 32;
        let vector = |seed: u64| -> Vec<f32> {
            let mut state = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
            (0..DIM)
                .map(|_| {
                    state ^= state << 13;
                    state ^= state >> 7;
                    state ^= state << 17;
                    (state >> 40) as f32 / (1u64 << 23) as f32 - 1.0
                })
                .collect()
        };
        let cosine = |a: &[f32], b: &[f32]| -> f64 {
            let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
            let na: f64 = a.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            let nb: f64 = b.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            dot / (na * nb)
        };

        let mut entries = Vec::new();
        let mut corpus: Vec<(String, Vec<f32>)> = Vec::new();
        for (seg_idx, quantization) in [
            kosha_core::VectorQuantization::F32,
            kosha_core::VectorQuantization::I8,
            kosha_core::VectorQuantization::F32,
            kosha_core::VectorQuantization::I8,
        ]
        .into_iter()
        .enumerate()
        {
            let seg = format!("seg{seg_idx}-{}", quantization.as_str());
            let mut w = SegmentWriter::new(SegmentId(seg.clone()), dir.join(&ns.0).join(&seg))
                .with_vector_quantization(kosha_segment::VectorQuantizationConfig::all(
                    quantization,
                ));
            for i in 0..300u64 {
                let id = format!("{seg}-{i}");
                let v = vector(seg_idx as u64 * 1000 + i);
                corpus.push((id.clone(), v.clone()));
                w.add_document(DocumentId(id), vec![Field::vector("emb", v)]);
            }
            let footer = w.finalize(Bm25Params::default()).unwrap();
            assert_eq!(
                footer.vector_fields.as_ref().unwrap()[0].quantization,
                quantization
            );
            entries.push(ManifestEntry {
                segment_id: SegmentId(seg),
                doc_count: 300,
            });
        }
        let manifest = Manifest {
            version: 1,
            segments: entries,
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            schema: None,
            retired: Default::default(),
            shards: None,
            branch: None,
        };
        let searcher = Searcher::new(dir.clone());
        let (mut hits_from_i8, mut total_recall) = (0usize, 0.0f64);
        let queries = 10u64;
        for q_seed in 0..queries {
            let query = vector(900_000 + q_seed);
            let mut q = mk_query("", 10);
            q.knn = Some(kosha_core::KnnQuery {
                query_text: None,
                embedding_model: None,
                field: "emb".into(),
                vector: query.clone(),
                k: 10,
                // Every posting of every segment: only quantization, not
                // the probe budget, could cost recall here.
                num_candidates: 10_000,
                filter: None,
                scoring: None,
                vectors: None,
            });
            let r = searcher.search(&ns, &manifest, &q, None).unwrap();
            let got: Vec<String> = r.results.iter().map(|h| h.doc_id.0.clone()).collect();
            let mut exact: Vec<(String, f64)> = corpus
                .iter()
                .map(|(id, v)| (id.clone(), cosine(&query, v)))
                .collect();
            exact.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
            let want: Vec<String> = exact.into_iter().take(10).map(|(id, _)| id).collect();
            assert_eq!(got.len(), 10);
            hits_from_i8 += got.iter().filter(|id| id.contains("-i8-")).count();
            total_recall += got.iter().filter(|id| want.contains(id)).count() as f64 / 10.0;
            // Scores are ordered and both formats speak the same units.
            assert!(r.results.windows(2).all(|w| w[0].score >= w[1].score));
        }
        assert!(hits_from_i8 > 0, "i8 segments contribute hits");
        let recall = total_recall / queries as f64;
        assert!(recall >= 0.99, "mixed-format recall@10 {recall}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn namespace_mixing_f32_i8_and_rabitq_segments_ranks_like_f32_brute_force() {
        // #210: an i8-quantized segment written next to f32 segments (a
        // namespace mid-migration) must rank as if every vector were f32:
        // the i8 segment rescores its shortlist from `doc_vectors.bin`, so
        // scores from both formats are the same exact cosine and merge
        // into one correct order. RaBitQ segments (vector index version
        // 5) rescore the same way and must merge into the same order.
        let dir = std::env::temp_dir().join(format!(
            "kosha-test-knn-mixed-quantization-rabitq-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        const DIM: usize = 32;
        let vector = |seed: u64| -> Vec<f32> {
            let mut state = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
            (0..DIM)
                .map(|_| {
                    state ^= state << 13;
                    state ^= state >> 7;
                    state ^= state << 17;
                    (state >> 40) as f32 / (1u64 << 23) as f32 - 1.0
                })
                .collect()
        };
        let cosine = |a: &[f32], b: &[f32]| -> f64 {
            let dot: f64 = a.iter().zip(b).map(|(x, y)| *x as f64 * *y as f64).sum();
            let na: f64 = a.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            let nb: f64 = b.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
            dot / (na * nb)
        };

        let mut entries = Vec::new();
        let mut corpus: Vec<(String, Vec<f32>)> = Vec::new();
        for (seg_idx, quantization) in [
            kosha_core::VectorQuantization::F32,
            kosha_core::VectorQuantization::I8,
            kosha_core::VectorQuantization::RaBitQ,
            kosha_core::VectorQuantization::F32,
            kosha_core::VectorQuantization::I8,
            kosha_core::VectorQuantization::RaBitQ,
        ]
        .into_iter()
        .enumerate()
        {
            let seg = format!("seg{seg_idx}-{}", quantization.as_str());
            let mut w = SegmentWriter::new(SegmentId(seg.clone()), dir.join(&ns.0).join(&seg))
                .with_vector_quantization(kosha_segment::VectorQuantizationConfig::all(
                    quantization,
                ));
            for i in 0..300u64 {
                let id = format!("{seg}-{i}");
                let v = vector(seg_idx as u64 * 1000 + i);
                corpus.push((id.clone(), v.clone()));
                w.add_document(DocumentId(id), vec![Field::vector("emb", v)]);
            }
            let footer = w.finalize(Bm25Params::default()).unwrap();
            assert_eq!(
                footer.vector_fields.as_ref().unwrap()[0].quantization,
                quantization
            );
            entries.push(ManifestEntry {
                segment_id: SegmentId(seg),
                doc_count: 300,
            });
        }
        let manifest = Manifest {
            version: 1,
            segments: entries,
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            schema: None,
            retired: Default::default(),
            shards: None,
            branch: None,
        };
        let searcher = Searcher::new(dir.clone());
        let (mut hits_from_i8, mut hits_from_rabitq, mut total_recall) = (0usize, 0usize, 0.0f64);
        let queries = 10u64;
        for q_seed in 0..queries {
            let query = vector(900_000 + q_seed);
            let mut q = mk_query("", 10);
            q.knn = Some(kosha_core::KnnQuery {
                query_text: None,
                embedding_model: None,
                field: "emb".into(),
                vector: query.clone(),
                k: 10,
                // Every posting of every segment: only quantization, not
                // the probe budget, could cost recall here.
                num_candidates: 10_000,
                filter: None,
                scoring: None,
                vectors: None,
            });
            let r = searcher.search(&ns, &manifest, &q, None).unwrap();
            let got: Vec<String> = r.results.iter().map(|h| h.doc_id.0.clone()).collect();
            let mut exact: Vec<(String, f64)> = corpus
                .iter()
                .map(|(id, v)| (id.clone(), cosine(&query, v)))
                .collect();
            exact.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
            let want: Vec<String> = exact.into_iter().take(10).map(|(id, _)| id).collect();
            assert_eq!(got.len(), 10);
            hits_from_i8 += got.iter().filter(|id| id.contains("-i8-")).count();
            hits_from_rabitq += got.iter().filter(|id| id.contains("-rabitq-")).count();
            total_recall += got.iter().filter(|id| want.contains(id)).count() as f64 / 10.0;
            // Scores are ordered and both formats speak the same units.
            assert!(r.results.windows(2).all(|w| w[0].score >= w[1].score));
        }
        assert!(hits_from_i8 > 0, "i8 segments contribute hits");
        assert!(hits_from_rabitq > 0, "rabitq segments contribute hits");
        let recall = total_recall / queries as f64;
        assert!(recall >= 0.99, "mixed-format recall@10 {recall}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn radius_aware_ranking_finds_the_diluted_neighbour_without_widening_the_budget() {
        // What `alpha = 1` (full radius weight) buys in the scenario proved
        // above, and what the `alpha = 0` default (#458) gives up: instead
        // of needing a budget wide enough to include every segment, the
        // radius-aware lower bound lets the diluted target segment qualify
        // at a budget that's still genuinely thin (15 of 51 segments).
        // Raw distance (the default) ranks it last. At 10M real vectors
        // the trade goes the other way (recall@10 0.97 vs 0.83 at the 5%
        // budget), so this pins the ranking with an explicit alpha rather
        // than through the process default.
        //
        // Same corpus as `thin_global_budget_can_bury_the_true_neighbour_in_a_diluted_centroid`
        // (true neighbour at 8°, opposite-facing diluter at 170°, 50
        // one-doc decoys at 20°-80°), but this time every segment writes at
        // the real default `vector_write_version()` (radius-aware) instead
        // of relying on num_candidates alone. The target centroid's raw
        // distance to the query is ~0.98 (worse than every decoy — old
        // ranking excludes it at any budget up to 50, as the sibling test
        // proves) but its *radius* (the diluter pulls the centroid ~89°
        // off zero-ish while the true neighbour sits only 8° off) is large
        // enough that the lower bound `(distance - radius).max(0.0)` drops
        // to ~0.14 — inside the 15 nearest lower bounds of the 51 total.
        let dir = std::env::temp_dir().join("kosha-test-knn-radius-aware-dilution");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());

        let unit = |deg: f32| {
            let r = deg.to_radians();
            vec![r.cos(), r.sin()]
        };

        let mut entries = Vec::new();

        let target_dir = dir.join(&ns.0).join("target");
        let mut tw = SegmentWriter::new(SegmentId("target".into()), target_dir);
        tw.add_document(
            DocumentId("true-nn".into()),
            vec![Field::vector("emb", unit(8.0))],
        );
        tw.add_document(
            DocumentId("diluter".into()),
            vec![Field::vector("emb", unit(170.0))],
        );
        tw.finalize(Bm25Params::default()).unwrap();
        entries.push(ManifestEntry {
            segment_id: SegmentId("target".into()),
            doc_count: 2,
        });

        const DECOYS: usize = 50;
        for i in 0..DECOYS {
            let deg = 20.0 + (i as f32) * (60.0 / (DECOYS as f32 - 1.0)); // 20°..80°
            let seg = format!("decoy{i:03}");
            let seg_dir = dir.join(&ns.0).join(&seg);
            let mut w = SegmentWriter::new(SegmentId(seg.clone()), seg_dir);
            w.add_document(
                DocumentId(format!("{seg}-d0")),
                vec![Field::vector("emb", unit(deg))],
            );
            w.finalize(Bm25Params::default()).unwrap();
            entries.push(ManifestEntry {
                segment_id: SegmentId(seg),
                doc_count: 1,
            });
        }

        let manifest = Manifest {
            version: 1,
            segments: entries,
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        // Rank of the target segment among all 51 by probe score, at an
        // explicit alpha (the process default would make this test depend
        // on KOSHA_KNN_PROBE_RADIUS_ALPHA).
        let target_rank = |alpha: f32| {
            let mut scores: Vec<(f32, String)> = manifest
                .segments
                .iter()
                .map(|e| {
                    let reader = kosha_segment::SegmentReader::open_with_options(
                        dir.join(&ns.0).join(&e.segment_id.0),
                        true,
                    )
                    .unwrap();
                    let d = reader
                        .knn_centroid_distances_with_alpha("emb", &[1.0, 0.0], alpha)
                        .unwrap();
                    let best = d.into_iter().fold(f32::INFINITY, f32::min);
                    (best, e.segment_id.0.clone())
                })
                .collect();
            scores.sort_by(|a, b| a.0.total_cmp(&b.0));
            scores.iter().position(|(_, id)| id == "target").unwrap()
        };
        const THIN_BUDGET: usize = 15; // well under the 51-segment corpus
        let full_radius = target_rank(1.0);
        assert!(
            full_radius < THIN_BUDGET,
            "alpha=1 must rank the diluted target inside a thin budget \
             ({THIN_BUDGET}); got rank {full_radius}"
        );
        let raw = target_rank(0.0);
        assert!(
            raw >= THIN_BUDGET,
            "alpha=0 (raw distance) ranks the diluted target outside the thin \
             budget, the documented trade-off; got rank {raw}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_degraded_segments_counts_a_segment_with_a_corrupt_vector_idx_body() {
        // `knn_search`/`knn_search_within` returning `Err` isn't the only
        // way a segment's vectors can go silently missing: a segment whose
        // `vector.idx` has a valid v2 header but a corrupt/truncated body
        // parses to nothing at open time and lands in the exact same
        // `None => Vec::new()` branch as a segment with no vector field at
        // all. Without checking `reader.vector_index_degraded()` there, this
        // segment would return a clean zero-hit result with no signal that
        // its true nearest neighbors are missing — the blind spot in the
        // original `knn_degraded_segments` (PR #152).
        let dir = std::env::temp_dir().join("kosha-test-knn-degraded-corrupt-body");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::vector("contentEmbedding", vec![1.0, 0.0, 0.0])],
        );
        w.add_document(
            DocumentId("d2".into()),
            vec![Field::vector("contentEmbedding", vec![0.0, 1.0, 0.0])],
        );
        w.finalize(Bm25Params::default()).unwrap();

        // Force the corrupt-body path: drop the sidecar (forces the eager
        // fallback), then truncate vector.idx's body so the eager parse
        // fails too, while its header stays valid — same recipe as
        // `kosha-segment`'s `corrupt_vector_idx_body_is_marked_degraded_not_silently_emptied`.
        std::fs::remove_file(seg_dir.join("vector.offsets")).unwrap();
        let idx_path = seg_dir.join("vector.idx");
        let mut bytes = std::fs::read(&idx_path).unwrap();
        bytes.truncate(bytes.len() - 3);
        std::fs::write(&idx_path, &bytes).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 2,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let mut q = mk_query("", 5);
        q.knn = Some(kosha_core::KnnQuery {
            query_text: None,
            embedding_model: None,
            field: "contentEmbedding".into(),
            vector: vec![1.0, 0.0, 0.0],
            k: 5,
            num_candidates: 10,
            filter: None,
            vectors: None,
            scoring: None,
        });
        let (r, stats) = searcher
            .search_with_stats(&ns, &manifest, &q, None)
            .unwrap();
        assert_eq!(
            r.results.len(),
            0,
            "the corrupt segment's vectors are genuinely unrecoverable"
        );
        assert_eq!(
            r.knn_degraded_segments,
            Some(1),
            "a segment with a corrupt vector.idx body must be counted as \
             degraded, not silently reported as a clean zero-hit result"
        );
        // Lost to an error, so reported as failed: the server answers 503.
        assert_eq!(stats.knn_failed_segments, vec![SegmentId("s1".into())]);
        // A corrupt body: the server may self-heal it by re-downloading.
        assert_eq!(stats.knn_corrupt_segments, vec![SegmentId("s1".into())]);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_degraded_segments_counts_a_segment_whose_hydration_errors() {
        // The other half of the degraded-segment signal: `knn_search`
        // itself returning `Err` (as opposed to the corrupt-body-at-open
        // case above, where the index never loads in the first place). The
        // lazy v2 path resolves centroids from `vector.offsets` at open and
        // only opens `vector.idx` for real when a probed posting needs
        // hydrating — so a *warm* reader (already cached from a prior
        // search on the same `Searcher`) whose backing file then vanishes
        // fails at hydration time, not at open time. `scan_posting`'s
        // one-shot admission also means the first touch of a posting is
        // never itself cached, so a second identical query is guaranteed to
        // re-hit disk rather than serve from the decoded-postings cache.
        let dir = std::env::temp_dir().join("kosha-test-knn-degraded-hydration-error");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::vector("contentEmbedding", vec![1.0, 0.0, 0.0])],
        );
        w.add_document(
            DocumentId("d2".into()),
            vec![Field::vector("contentEmbedding", vec![0.0, 1.0, 0.0])],
        );
        w.finalize(Bm25Params::default()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 2,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let mut q = mk_query("", 5);
        q.knn = Some(kosha_core::KnnQuery {
            query_text: None,
            embedding_model: None,
            field: "contentEmbedding".into(),
            vector: vec![1.0, 0.0, 0.0],
            k: 5,
            num_candidates: 10,
            filter: None,
            vectors: None,
            scoring: None,
        });

        // First call: vector.idx is present, opens and hydrates normally,
        // warming this segment into the searcher's own SegmentCache (keyed
        // by namespace/segment/load_vectors — reused as-is by the next
        // call, not reopened from disk).
        let (warm, warm_stats) = searcher
            .search_with_stats(&ns, &manifest, &q, None)
            .unwrap();
        assert_eq!(warm.knn_degraded_segments, Some(0));
        assert!(warm_stats.knn_failed_segments.is_empty());

        // Now the file disappears. The already-open reader still has it
        // resident in `vector_idx_path`, so the segment stays "present" as
        // far as the cache/open path is concerned — only the next
        // hydration attempt discovers it's gone.
        std::fs::remove_file(seg_dir.join("vector.idx")).unwrap();

        let (r, stats) = searcher
            .search_with_stats(&ns, &manifest, &q, None)
            .unwrap();
        assert_eq!(
            r.results.len(),
            0,
            "hydration failed, so this segment has no vector hits to return"
        );
        assert_eq!(
            r.knn_degraded_segments,
            Some(1),
            "a segment whose knn_search errors must be counted as degraded"
        );
        // Lost to an error, so reported as failed: the server answers 503.
        assert_eq!(stats.knn_failed_segments, vec![SegmentId("s1".into())]);
        // Not a corrupt index: nothing to re-download.
        assert!(stats.knn_corrupt_segments.is_empty());

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// 40 unit vectors around a circle, doc `i` at angle `i·9°`, each
    /// tagged with a `parity` keyword — the shared fixture for the kNN
    /// over-fetch tests below. Returns the corpus dir + manifest.
    fn knn_circle_corpus_with_parity(dir_name: &str) -> (std::path::PathBuf, Manifest) {
        let dir = std::env::temp_dir().join(dir_name);
        let _ = std::fs::remove_dir_all(&dir);
        let seg_dir = dir.join("test").join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..40u32 {
            let angle = (i as f32) * std::f32::consts::PI / 20.0;
            let parity = if i % 2 == 0 { "even" } else { "odd" };
            w.add_document(
                DocumentId(format!("d{i}")),
                vec![
                    Field::vector("contentEmbedding", vec![angle.cos(), angle.sin(), 0.0, 0.0]),
                    Field::keyword("parity", parity),
                ],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 40,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        (dir, manifest)
    }

    fn mk_knn_circle_query(k: usize, filter: Option<kosha_core::FilterClause>) -> SearchQuery {
        let mut q = mk_query("", k);
        q.knn = Some(kosha_core::KnnQuery {
            query_text: None,
            embedding_model: None,
            field: "contentEmbedding".into(),
            vector: vec![1.0, 0.0, 0.0, 0.0], // exact match for d0
            k,
            num_candidates: 40,
            filter,
            vectors: None,
            scoring: None,
        });
        q
    }

    #[test]
    fn knn_scoped_filter_restricts_candidates_not_silently_ignored() {
        // `KnnQuery.filter` was accepted on the wire and silently ignored —
        // a filtered vector search returned unfiltered neighbors. The
        // query vector sits exactly on d0 ("even"); filtering to "odd"
        // must return only odd docs, led by the nearest odd neighbors
        // (d1 and d39, ±9° away).
        let (dir, manifest) = knn_circle_corpus_with_parity("kosha-test-knn-scoped-filter");
        let ns = NamespaceId("test".into());
        let searcher = Searcher::new(dir.clone());
        let q = mk_knn_circle_query(
            5,
            Some(kosha_core::FilterClause::Term {
                term: std::collections::HashMap::from([("parity".into(), "odd".into())]),
            }),
        );
        let r = searcher.search(&ns, &manifest, &q, None).unwrap();
        let got: Vec<&str> = r.results.iter().map(|h| h.doc_id.0.as_str()).collect();
        assert_eq!(
            r.results.len(),
            5,
            "filtered kNN page came up short: {got:?}"
        );
        for id in &got {
            let i: u32 = id[1..].parse().unwrap();
            assert!(
                i % 2 == 1,
                "knn.filter=odd returned an even doc {id}: {got:?}"
            );
        }
        assert!(
            got.contains(&"d1") && got.contains(&"d39"),
            "nearest odd neighbors missing: {got:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn knn_overfetch_survives_tombstoned_nearest_neighbors() {
        // Tombstones are applied after the per-segment kNN cut to `k` —
        // without over-fetch, deleting the k nearest docs returns an empty
        // page even though 37 live vectors remain. Tombstone the three
        // nearest to the query (d0, d1, d39) and ask for k=3: the page
        // must still hold three live docs, led by the next ring (d2, d38).
        let (dir, manifest) = knn_circle_corpus_with_parity("kosha-test-knn-tombstone-overfetch");
        let ns = NamespaceId("test".into());
        let searcher = Searcher::new(dir.clone());
        let tombstones = std::collections::HashMap::from([(
            SegmentId("s1".into()),
            std::collections::HashSet::from([0u32, 1, 39]),
        )]);
        let q = mk_knn_circle_query(3, None);
        let r = searcher
            .search(&ns, &manifest, &q, Some(&tombstones))
            .unwrap();
        let got: Vec<&str> = r.results.iter().map(|h| h.doc_id.0.as_str()).collect();
        assert_eq!(
            r.results.len(),
            3,
            "kNN page shorted by tombstoned neighbors: {got:?}"
        );
        for id in ["d0", "d1", "d39"] {
            assert!(!got.contains(&id), "tombstoned doc {id} returned: {got:?}");
        }
        assert!(
            got.contains(&"d2") && got.contains(&"d38"),
            "next-nearest live docs missing: {got:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn full_page_materialization_needs_doc_store_on_disk_but_scoring_does_not() {
        // Structural proof of the lazy doc_store contract (issue #37
        // follow-up): opening a segment and scoring/counting hits never
        // reads `doc_store.bin`'s full field content — only the small
        // `doc_store.offsets` sidecar (doc_id + field_length per doc,
        // proportional to document count, not content size). Full field
        // content is read from disk only when a query actually materializes
        // a result page, and only for the documents on that page.
        let dir = std::env::temp_dir().join("kosha-test-lazy-doc-store-contract");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::text("t", "hello world")],
        );
        w.finalize(Bm25Params::default()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 1,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        // Fresh searcher (no warm in-memory segment cache) so opening the
        // segment for these searches goes through the real `try_read_doc_index`
        // -> `DocStoreAccess::Lazy` path, not a cached `Eager` fallback from
        // an earlier call in this test.
        let searcher = Searcher::new(dir.clone());

        // `doc_store.bin` deleted entirely, `doc_store.offsets` untouched.
        std::fs::remove_file(seg_dir.join("doc_store.bin")).unwrap();

        // max_results: 0 never materializes a page, so it must succeed and
        // report the correct count purely from resident metadata.
        let count_only = mk_query("hello", 0);
        let counted = searcher
            .search(&ns, &manifest, &count_only, None)
            .expect("scoring/counting must not require doc_store.bin on disk");
        assert_eq!(counted.total_hits, 1);
        assert!(counted.results.is_empty());

        // A query that actually needs to return the document correctly
        // fails now that its full content is genuinely gone — this is the
        // honest lazy-loading tradeoff, not a bug: the in-memory cache never
        // held full field content in the first place, so there is nothing
        // to silently fall back to.
        let full_page = mk_query("hello", 10);
        let err = searcher
            .search(&ns, &manifest, &full_page, None)
            .expect_err("materializing the page must surface the missing doc_store.bin");
        assert!(matches!(err, KoshaError::Io(_)), "unexpected error: {err}");

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn ids_only_page_never_reads_the_doc_store() {
        // DEC-3203: `source_includes: []` returns ids and scores only, so a
        // page must materialize without the doc store — a cold ids-only
        // search used to make a ranged S3 GET per page segment just to drop
        // every field. A highlight still reads the field it marks up.
        let dir = std::env::temp_dir().join("kosha-test-ids-only-page");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::text("t", "hello world")],
        );
        w.add_document(
            DocumentId("d2".into()),
            vec![Field::text("t", "hello there")],
        );
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 2,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let mut full = mk_query("hello", 10);
        let expected = searcher.search(&ns, &manifest, &full, None).unwrap();

        std::fs::remove_file(seg_dir.join("doc_store.bin")).unwrap();
        let searcher = Searcher::new(dir.clone());
        full.source_includes = Some(Vec::new());
        let ids_only = searcher
            .search(&ns, &manifest, &full, None)
            .expect("an ids-only page must not need doc_store.bin");
        let got: Vec<_> = ids_only
            .results
            .iter()
            .map(|d| (d.doc_id.0.clone(), d.score.to_bits()))
            .collect();
        let want: Vec<_> = expected
            .results
            .iter()
            .map(|d| (d.doc_id.0.clone(), d.score.to_bits()))
            .collect();
        assert_eq!(got, want, "same ids, same order, same score bits");
        assert!(ids_only.results.iter().all(|d| d.fields.is_empty()));
        assert_eq!(ids_only.total_hits, expected.total_hits);

        full.highlight = Some(kosha_core::HighlightConfig {
            fields: Vec::new(),
            pre_tags: None,
            post_tags: None,
            legacy_single_field: true,
        });
        assert!(
            searcher.search(&ns, &manifest, &full, None).is_err(),
            "a highlighted page still reads the field it marks up"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn search_with_doc_store_hydrator_fetches_only_page_segments_on_demand() {
        // Scoring-set-only hydration contract (Option A): a cold search has
        // only the offsets sidecar locally, so the hydrator is asked to
        // fetch & persist the **whole `doc_store.bin`** for each distinct
        // segment holding a page hit — once per segment, never per doc.
        // Includes a non-matching segment that must never be requested, a
        // count-only call that must not invoke the hydrator at all, and the
        // key warm-path assertion: a second identical query must skip the
        // hydrator entirely because the file is now local (the 350 ms → ~ms
        // warm-latency win).
        let dir = std::env::temp_dir().join("kosha-test-doc-store-on-demand");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());

        let build_seg = |id: &str, doc_id: &str, text: &str| {
            let seg_dir = dir.join(&ns.0).join(id);
            let mut w = SegmentWriter::new(SegmentId(id.into()), seg_dir.clone());
            w.add_document(DocumentId(doc_id.into()), vec![Field::text("t", text)]);
            w.finalize(Bm25Params::default()).unwrap();
            // Back up doc_store.bin, then remove it to model scoring-set-only
            // hydration: offsets sidecar present, doc_store.bin absent.
            let bin = seg_dir.join("doc_store.bin");
            std::fs::copy(&bin, seg_dir.join("doc_store.bin.bak")).unwrap();
            std::fs::remove_file(&bin).unwrap();
            seg_dir
        };

        let _s1 = build_seg("s1", "d1", "hello world");
        let _s2 = build_seg("s2", "d2", "hello moon");
        let s3 = build_seg("s3", "d3", "completely unrelated"); // no hit

        let manifest = Manifest {
            version: 1,
            segments: ["s1", "s2", "s3"]
                .into_iter()
                .map(|id| ManifestEntry {
                    segment_id: SegmentId(id.into()),
                    doc_count: 1,
                })
                .collect(),
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        // Fresh searcher so each segment is actually opened (Lazy), not
        // served from a warm cache populated by an earlier call here.
        let searcher = Searcher::new(dir.clone());

        let requested: Arc<Mutex<Vec<PathBuf>>> = Arc::new(Mutex::new(Vec::new()));
        let requested_clone = Arc::clone(&requested);
        let ledger = Arc::clone(&searcher.ledger);
        // Test-side stand-in for an S3 whole-file fetch of `doc_store.bin`:
        // restore the backed-up file to its on-disk path so the segment's
        // local `doc_record_full` seek+read succeeds, exactly as it would
        // after the real hydrator's `ensure_files_local` lands the file.
        let ensure_doc_store = move |segs: &[PageSegment<'_>]| {
            assert_eq!(ledger.state.lock().unwrap().active, 1);
            for seg in segs {
                let seg = seg.segment_dir;
                requested_clone.lock().unwrap().push(seg.to_path_buf());
                let _ = std::fs::copy(seg.join("doc_store.bin.bak"), seg.join("doc_store.bin"));
            }
        };

        let mut fused: SearchQuery = serde_json::from_value(serde_json::json!({
            "query_text": "",
            "rank_by": {"rrf": {"queries": [{"query_text": "hello"}, {"query_text": "moon"}]}},
            "max_results": 0
        }))
        .unwrap();
        let run_fused = |q: &SearchQuery| {
            searcher
                .search_with_doc_store_hydrator(&ns, &manifest, q, None, Some(&ensure_doc_store))
                .unwrap()
                .0
        };
        assert_eq!(run_fused(&fused).total_hits, 2);
        assert!(requested.lock().unwrap().is_empty());
        fused.max_results = 1;
        assert_eq!(run_fused(&fused).results[0].doc_id.0, "d2");
        assert_eq!(ledger_snapshot(&searcher).2, 0);
        assert_eq!(*requested.lock().unwrap(), [dir.join("test/s2")]);
        std::fs::remove_file(dir.join("test/s2/doc_store.bin")).unwrap();
        requested.lock().unwrap().clear();

        let q = mk_query("hello", 5);
        let r = searcher
            .search_with_doc_store_hydrator(&ns, &manifest, &q, None, Some(&ensure_doc_store))
            .map(|(result, _stats)| result)
            .expect("materialize must succeed from hydrator-persisted doc_store");
        assert_eq!(r.total_hits, 2);
        assert_eq!(r.results.len(), 2);
        assert!(r.results.iter().any(|d| d.doc_id.0 == "d1"));
        assert!(r.results.iter().any(|d| d.doc_id.0 == "d2"));

        // Exactly the two page-hits' *segments* were requested (one path
        // each — Option A dedups by segment, not per doc); the
        // non-matching s3 segment must never reach the hydrator.
        let req = requested.lock().unwrap();
        assert_eq!(
            req.len(),
            2,
            "expected exactly the 2 page-hit segment paths, got {req:?}"
        );
        assert!(
            req.iter().all(|p| *p != s3),
            "non-matching segment s3 was hydrated"
        );
        drop(req);

        // A count-only query materializes no page → hydrator untouched.
        let before = requested.lock().unwrap().len();
        let count_only = mk_query("hello", 0);
        let counted = searcher
            .search_with_doc_store_hydrator(
                &ns,
                &manifest,
                &count_only,
                None,
                Some(&ensure_doc_store),
            )
            .map(|(result, _stats)| result)
            .unwrap();
        assert_eq!(counted.total_hits, 2);
        assert!(counted.results.is_empty());
        assert_eq!(
            requested.lock().unwrap().len(),
            before,
            "count-only query must not trigger doc_store hydration"
        );

        // Warm-path assertion (the whole point of Option A): a second
        // identical query skips the hydrator entirely because
        // `doc_store.bin` is now persisted for both page-hit segments.
        let before_warm = requested.lock().unwrap().len();
        let r2 = searcher
            .search_with_doc_store_hydrator(&ns, &manifest, &q, None, Some(&ensure_doc_store))
            .map(|(result, _stats)| result)
            .expect("warm query must materialize from local doc_store");
        assert_eq!(r2.total_hits, 2);
        assert_eq!(r2.results.len(), 2);
        assert_eq!(
            requested.lock().unwrap().len(),
            before_warm,
            "warm query must NOT re-invoke the hydrator — doc_store.bin is now local"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn hydrator_gets_page_doc_spans_and_span_cache_serves_warm_repeat() {
        // #245 Option B contract: the hydrator is told exactly which page
        // documents are missing, per segment; it persists only their byte
        // spans into the sparse span cache (never a partial file at the
        // real `doc_store.bin` path), the searcher materializes from those
        // spans, and a warm repeat finds every document local and never
        // calls the hydrator again.
        use kosha_segment::span_cache;
        let dir = std::env::temp_dir().join("kosha-test-doc-store-spans");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        for i in 0..200 {
            let text = if i % 50 == 7 {
                "needle hay"
            } else {
                "hay only"
            };
            w.add_document(
                DocumentId(format!("d{i}")),
                vec![Field::text("t", format!("{text} filler {i}"))],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let full = std::fs::read(seg_dir.join("doc_store.bin")).unwrap();
        std::fs::remove_file(seg_dir.join("doc_store.bin")).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 200,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            schema: None,
            retired: Default::default(),
            shards: None,
            branch: None,
        };
        let searcher = Searcher::new(dir.clone());
        let calls: Arc<Mutex<Vec<Vec<u32>>>> = Arc::new(Mutex::new(Vec::new()));
        let calls_in = Arc::clone(&calls);
        let ensure = move |segs: &[PageSegment<'_>]| {
            for seg in segs {
                calls_in.lock().unwrap().push(seg.doc_seqs.clone());
                for &seq in &seg.doc_seqs {
                    let (off, len) = seg.reader.doc_span(seq).unwrap();
                    let (s, e) = (off as usize, off as usize + len as usize);
                    let spans = span_cache::spans_dir(seg.segment_dir, "doc_store.bin");
                    std::fs::create_dir_all(&spans).unwrap();
                    std::fs::write(
                        spans.join(span_cache::span_file_name(s as u64, e as u64)),
                        &full[s..e],
                    )
                    .unwrap();
                }
            }
        };
        let q = mk_query("needle", 10);
        let (r, _) = searcher
            .search_with_doc_store_hydrator(&ns, &manifest, &q, None, Some(&ensure))
            .unwrap();
        assert_eq!(r.results.len(), 4);
        for doc in &r.results {
            let i: usize = doc.doc_id.0[1..].parse().unwrap();
            assert_eq!(doc.fields[0].value, format!("needle hay filler {i}"));
        }
        {
            let calls = calls.lock().unwrap();
            assert_eq!(calls.len(), 1, "one hydrator call per query");
            let mut seqs = calls[0].clone();
            seqs.sort_unstable();
            assert_eq!(seqs, vec![7, 57, 107, 157], "exactly the page's docs");
        }
        assert!(!seg_dir.join("doc_store.bin").exists());

        let (r2, _) = searcher
            .search_with_doc_store_hydrator(&ns, &manifest, &q, None, Some(&ensure))
            .unwrap();
        assert_eq!(r2.results.len(), 4);
        assert_eq!(calls.lock().unwrap().len(), 1, "warm repeat must not fetch");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn legacy_segment_without_offsets_sidecar_still_searches() {
        // Backward compatibility: a segment written before `doc_store.offsets`
        // existed (or one where the sidecar was otherwise lost) has no offset
        // table to open lazily. `try_read_doc_index` returns `None` for a
        // missing file, so `SegmentReader` falls back to `DocStoreAccess::Eager`
        // — the exact full-parse behavior every segment used before lazy
        // loading, not a degraded or partial mode.
        let dir = std::env::temp_dir().join("kosha-test-legacy-no-offsets-sidecar");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::text("t", "hello world")],
        );
        w.add_document(
            DocumentId("d2".into()),
            vec![Field::text("t", "hello moon")],
        );
        w.finalize(Bm25Params::default()).unwrap();

        std::fs::remove_file(seg_dir.join("doc_store.offsets")).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 2,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let q = mk_query("hello", 10);
        let r = searcher
            .search(&ns, &manifest, &q, None)
            .expect("missing offsets sidecar must fall back to eager parse, not fail");
        assert_eq!(r.total_hits, 2);
        assert_eq!(r.results.len(), 2);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn corrupted_offsets_sidecar_falls_back_safely() {
        // A `doc_store.offsets` that exists but is corrupt (truncated header,
        // or a declared doc_count that disagrees with footer.json) must not
        // panic or silently return wrong data — `try_read_doc_index` detects
        // the mismatch and returns `None`, degrading to the same full-parse
        // path as a legacy segment: slower, but still correct.
        let dir = std::env::temp_dir().join("kosha-test-corrupted-offsets-sidecar");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        w.add_document(
            DocumentId("d1".into()),
            vec![Field::text("t", "hello world")],
        );
        w.add_document(
            DocumentId("d2".into()),
            vec![Field::text("t", "hello moon")],
        );
        w.finalize(Bm25Params::default()).unwrap();

        // Corrupt the declared doc_count so it disagrees with footer.json's
        // doc_count (2), tripping the mismatch check rather than the
        // truncation check.
        std::fs::write(seg_dir.join("doc_store.offsets"), 99u32.to_le_bytes()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 2,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let q = mk_query("hello", 10);
        let r = searcher
            .search(&ns, &manifest, &q, None)
            .expect("corrupt offsets sidecar must fall back safely, not panic or error");
        assert_eq!(r.total_hits, 2);
        assert_eq!(r.results.len(), 2);

        // Also cover the truncated-header case (fewer than 4 bytes).
        std::fs::write(seg_dir.join("doc_store.offsets"), [0u8, 1u8]).unwrap();
        let searcher2 = Searcher::new(dir.clone());
        let r2 = searcher2
            .search(&ns, &manifest, &q, None)
            .expect("truncated offsets header must fall back safely, not panic or error");
        assert_eq!(r2.total_hits, 2);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn bounded_topk_selection_matches_full_sort_order() {
        // Regression test for issue #37's second fix: bounded top-k
        // selection (select_nth_unstable_by + a small sort of just the
        // page) instead of a full sort over every candidate. Cross-checks
        // against an unbounded query (max_results covering every hit) to
        // prove the partial-selection path returns exactly the same order
        // — for both the first page and a page deep enough to require
        // `from > 0`, rather than hand-deriving expected BM25 scores.
        let dir = std::env::temp_dir().join("kosha-test-bounded-topk");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        let n = 60usize;
        for i in 0..n {
            // Distinct term frequency per doc so BM25 scores are unique and
            // the ranking is deterministic, not tie-broken by doc_id alone.
            let repeats = i + 1;
            let content = format!("{}filler", "contract ".repeat(repeats));
            w.add_document(
                DocumentId(format!("doc-{i:03}")),
                vec![Field::text("content", content)],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());

        let full = searcher
            .search(&ns, &manifest, &mk_query("contract", n), None)
            .unwrap();
        assert_eq!(full.total_hits, n);
        assert_eq!(full.results.len(), n);

        // First page: bounded selection with `to` well under total_hits.
        let page1 = searcher
            .search(&ns, &manifest, &mk_query("contract", 5), None)
            .unwrap();
        assert_eq!(page1.total_hits, n);
        assert_eq!(
            page1
                .results
                .iter()
                .map(|d| d.doc_id.0.clone())
                .collect::<Vec<_>>(),
            full.results[0..5]
                .iter()
                .map(|d| d.doc_id.0.clone())
                .collect::<Vec<_>>(),
            "bounded top-k page must match the equivalent slice of a full sort"
        );

        // Deep page: from > 0, still `to < total_hits` — exercises the
        // select_nth_unstable_by partition at a non-trivial offset.
        let mut deep_query = mk_query("contract", 5);
        deep_query.from = 20;
        let page2 = searcher.search(&ns, &manifest, &deep_query, None).unwrap();
        assert_eq!(
            page2
                .results
                .iter()
                .map(|d| d.doc_id.0.clone())
                .collect::<Vec<_>>(),
            full.results[20..25]
                .iter()
                .map(|d| d.doc_id.0.clone())
                .collect::<Vec<_>>(),
            "deep bounded page (from>0) must match the equivalent slice of a full sort"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn term_bloom_skips_segments_without_query_terms() {
        let dir = std::env::temp_dir().join("kosha-test-term-bloom-prune");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());

        let seg_a = dir.join(&ns.0).join("s-match");
        let mut wa = SegmentWriter::new(SegmentId("s-match".into()), seg_a.clone());
        wa.add_document(
            DocumentId("hit".into()),
            vec![Field::text("content", "contract language here")],
        );
        wa.finalize(Bm25Params::default()).unwrap();

        let seg_b = dir.join(&ns.0).join("s-miss");
        let mut wb = SegmentWriter::new(SegmentId("s-miss".into()), seg_b.clone());
        wb.add_document(
            DocumentId("miss".into()),
            vec![Field::text("content", "completely different vocabulary")],
        );
        wb.finalize(Bm25Params::default()).unwrap();

        let miss_footer = SegmentReader::read_footer(&seg_b).unwrap();
        assert!(
            !kosha_core::segment_may_contain_terms(
                &["contract".into()],
                kosha_core::TermBloomMode::And,
                miss_footer.term_bloom.as_ref(),
            ),
            "segment without 'contract' must be bloom-prunable"
        );

        let manifest = Manifest {
            version: 1,
            segments: vec![
                ManifestEntry {
                    segment_id: SegmentId("s-match".into()),
                    doc_count: 1,
                },
                ManifestEntry {
                    segment_id: SegmentId("s-miss".into()),
                    doc_count: 1,
                },
            ],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let r = searcher
            .search(&ns, &manifest, &mk_query("contract", 10), None)
            .unwrap();
        assert_eq!(r.total_hits, 1);
        assert_eq!(r.results[0].doc_id.0, "hit");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn multi_term_and_intersects_and_scores() {
        // Multi-term queries take the AND path (HashMap posting lookup).
        // Docs must contain *all* terms; partial matches are excluded.
        let dir = std::env::temp_dir().join("kosha-test-multi-term-and");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        w.add_document(
            DocumentId("both".into()),
            vec![Field::text("content", "contract dispute clause")],
        );
        w.add_document(
            DocumentId("only-contract".into()),
            vec![Field::text("content", "contract alone")],
        );
        w.add_document(
            DocumentId("only-dispute".into()),
            vec![Field::text("content", "dispute alone")],
        );
        w.finalize(Bm25Params::default()).unwrap();

        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 3,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let r = searcher
            .search(&ns, &manifest, &mk_query("contract dispute", 10), None)
            .unwrap();
        assert_eq!(r.total_hits, 1);
        assert_eq!(r.results[0].doc_id.0, "both");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Force the general (pre-WAND) scoring path for a query that would
    /// otherwise take the block-max gate: a `search_after` cursor of one
    /// empty string fails the gate's emptiness check, while
    /// `candidate_is_strictly_after_cursor` under default ranking reads it
    /// as `doc_id > ""` — true for every real doc, so the result set and
    /// ranking are untouched. (`from` is ignored under search_after, so
    /// only compare from=0 pages through this helper.)
    fn force_legacy(mut q: SearchQuery) -> SearchQuery {
        q.search_after = crate::force_legacy_search_after();
        q
    }

    /// Corpus for the multi-term WAND parity tests: `n` docs that all
    /// contain "alpha", ~2/3 contain "beta", ~1/3 contain "gamma", with
    /// per-doc-distinct term frequencies and padded (varying) field lengths
    /// so BM25 scores are unique and blocks get real UB spread. `n` well
    /// above 128 forces multiple postings blocks per term.
    fn mk_wand_corpus(dir: &std::path::Path, ns: &str, n: usize) -> Manifest {
        let seg_dir = dir.join(ns).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..n {
            let mut content = format!("{}x", "alpha ".repeat(i % 7 + 1));
            if i % 3 != 0 {
                content.push_str(&format!(" {}", "beta ".repeat(i % 5 + 1)));
            }
            // Modulus independent of beta's, so "alpha beta gamma" has a
            // real (i%3≠0 ∧ i%4==0) intersection instead of an empty one.
            if i % 4 == 0 {
                content.push_str(&format!(" {}", "gamma ".repeat(i % 4 + 1)));
            }
            // Distinct padding length → distinct length norms → no score ties.
            content.push_str(&" pad".repeat(i % 11));
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text("content", content)],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        }
    }

    fn page_ids(r: &SearchResult) -> Vec<String> {
        r.results.iter().map(|d| d.doc_id.0.clone()).collect()
    }

    fn mk_query_or(text: &str, max: usize) -> SearchQuery {
        let mut q = mk_query(text, max);
        q.operator = Some(kosha_core::QueryOperator::Or);
        q
    }

    /// Corpus for the OR/WAND join tests: "solar" on every third doc,
    /// "lunar" on every fourth — genuine partial overlap (every twelfth
    /// doc has both), so the union differs from either term alone AND
    /// from their intersection, and dedup at the overlap actually gets
    /// exercised. `n=600` spans several 128-posting blocks per term, same
    /// as `mk_wand_corpus`.
    fn mk_or_corpus(dir: &std::path::Path, ns: &str, n: usize) -> Manifest {
        let seg_dir = dir.join(ns).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..n {
            let mut content = String::new();
            if i % 3 == 0 {
                content.push_str(&"solar ".repeat(i % 6 + 1));
            }
            if i % 4 == 0 {
                content.push_str(&"lunar ".repeat(i % 5 + 1));
            }
            if content.is_empty() {
                content.push_str("filler ");
            }
            // Distinct padding length → distinct length norms → no score ties.
            content.push_str(&"pad ".repeat(i % 11));
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text("content", content)],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        }
    }

    /// Two-segment namespace whose segments are written at the given
    /// inverted-postings versions (#386): same documents as
    /// `mk_or_corpus`, split across `s1` (even docs) and `s2` (odd docs).
    fn mk_versioned_namespace(dir: &std::path::Path, ns: &str, versions: [u32; 2]) -> Manifest {
        let mut manifest = mk_or_corpus(dir, "__unused", 0);
        manifest.segments.clear();
        let _ = std::fs::remove_dir_all(dir.join("__unused"));
        for (s, version) in versions.into_iter().enumerate() {
            let id = SegmentId(format!("s{}", s + 1));
            let mut w = SegmentWriter::new(id.clone(), dir.join(ns).join(&id.0))
                .with_postings_write_version(version);
            let mut count = 0;
            for i in (s..1_200).step_by(2) {
                let mut content = String::new();
                if i % 3 == 0 {
                    content.push_str(&"solar ".repeat(i % 6 + 1));
                }
                if i % 4 == 0 {
                    content.push_str(&"lunar ".repeat(i % 5 + 1));
                }
                if i % 7 == 0 {
                    content.push_str("eclipse solar ");
                }
                content.push_str("filler ");
                content.push_str(&"pad ".repeat(i % 11));
                w.add_document(
                    DocumentId(format!("doc-{i:04}")),
                    vec![Field::text("content", content)],
                );
                count += 1;
            }
            w.finalize(Bm25Params::default()).unwrap();
            manifest.segments.push(ManifestEntry {
                segment_id: id,
                doc_count: count,
            });
        }
        manifest
    }

    /// Mixed v5/v6/v7 namespace (#386): a namespace whose segments differ only
    /// in postings version returns exactly the all-v5 namespace's hits,
    /// totals and scores — AND/WAND, OR/WAND, single-term and phrase.
    #[test]
    fn mixed_postings_versions_match_all_v5() {
        use kosha_segment::{
            BITPACKED_SKIP_SPLIT_INVERTED_VERSION as V6, PACKED_POSITIONS_INVERTED_VERSION as V7,
            SKIP_SPLIT_INVERTED_VERSION as V5,
        };
        let dir =
            std::env::temp_dir().join(format!("kosha-test-mixed-v5-v6-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let base = NamespaceId("v5v5".into());
        let base_manifest = mk_versioned_namespace(&dir, &base.0, [V5, V5]);
        let searcher = Searcher::new(dir.clone());
        let mut queries = vec![
            mk_query("solar", 20),
            mk_query("solar lunar", 20),
            mk_query_or("solar lunar eclipse", 20),
            mk_query_or("filler pad", 50),
            force_legacy(mk_query_or("solar lunar", 20)),
        ];
        let mut phrase = mk_query("", 20);
        phrase.match_phrase = Some(
            serde_json::from_value(
                serde_json::json!({"field": "content", "phrase": "eclipse solar"}),
            )
            .unwrap(),
        );
        queries.push(phrase);
        for (name, versions) in [
            ("v5v6", [V5, V6]),
            ("v6v5", [V6, V5]),
            ("v6v6", [V6, V6]),
            ("v5v7", [V5, V7]),
            ("v7v6", [V7, V6]),
            ("v7v7", [V7, V7]),
        ] {
            let ns = NamespaceId(name.into());
            let manifest = mk_versioned_namespace(&dir, name, versions);
            for q in &queries {
                let want = searcher.search(&base, &base_manifest, q, None).unwrap();
                let got = searcher.search(&ns, &manifest, q, None).unwrap();
                assert!(
                    want.total_hits > 0,
                    "{name}: query must match: {:?}",
                    q.query_text
                );
                assert_eq!(got.total_hits, want.total_hits, "{name} {:?}", q.query_text);
                assert_eq!(page_ids(&got), page_ids(&want), "{name} {:?}", q.query_text);
                for (g, w) in got.results.iter().zip(&want.results) {
                    assert_eq!(
                        g.score.to_bits(),
                        w.score.to_bits(),
                        "{name} {}",
                        g.doc_id.0
                    );
                }
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn or_query_matches_legacy_path_union_ranking_and_scores() {
        // Same contract as the AND parity test above, but for `operator:
        // or`: the WAND pivot join must be observably identical to the
        // general path's HashMap union branch — same total_hits (both
        // exact here, well under the default cap), same page order, same
        // scores.
        let dir = std::env::temp_dir().join("kosha-test-or-wand-parity");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_or_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        let wand = searcher
            .search(&ns, &manifest, &mk_query_or("solar lunar", 10), None)
            .unwrap();
        let legacy = searcher
            .search(
                &ns,
                &manifest,
                &force_legacy(mk_query_or("solar lunar", 10)),
                None,
            )
            .unwrap();
        assert!(wand.total_hits > 0, "corpus must have union members");
        assert_eq!(
            wand.total_hits, legacy.total_hits,
            "OR total_hits must match the legacy union scan"
        );
        assert_eq!(wand.total_hits_relation, TotalHitsRelation::Eq);
        assert_eq!(
            page_ids(&wand),
            page_ids(&legacy),
            "OR page ranking must match the legacy path"
        );
        for (w_doc, l_doc) in wand.results.iter().zip(legacy.results.iter()) {
            assert!(
                (w_doc.score - l_doc.score).abs() < 1e-9,
                "score mismatch on {}: {} vs {}",
                w_doc.doc_id.0,
                w_doc.score,
                l_doc.score
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn or_query_total_hits_equals_exact_union_cardinality() {
        // i%3==0: 200 docs (0..600). i%4==0: 150 docs. i%12==0 (both): 50
        // docs. |union| = 200 + 150 - 50 = 300 — hand-computed so a dedup
        // bug (double-counting the overlap, or an off-by-one in the pivot
        // skip) shows up as a wrong number, not just "some number > 0".
        let dir = std::env::temp_dir().join("kosha-test-or-union-cardinality");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_or_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        let r = searcher
            .search(&ns, &manifest, &mk_query_or("solar lunar", 10), None)
            .unwrap();
        assert_eq!(r.total_hits, 300);
        assert_eq!(r.total_hits_relation, TotalHitsRelation::Eq);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn query_without_operator_still_defaults_to_and() {
        // Back-compat pin: the exact same corpus/terms as the OR test
        // above, but through the default (no `operator` set) query —
        // must reduce to the intersection (i%12==0 → 50 docs), not the
        // union, proving `SearchQuery::operator: None` changed nothing
        // about pre-existing AND behavior.
        let dir = std::env::temp_dir().join("kosha-test-and-default-still-and");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_or_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        let r = searcher
            .search(&ns, &manifest, &mk_query("solar lunar", 10), None)
            .unwrap();
        assert_eq!(r.total_hits, 50);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn or_query_caps_total_hits_and_marks_gte() {
        // A per-query cap well under the true union size (300): the WAND
        // OR join must stop early once ranking is settled and the budget
        // is met, report exactly the cap with relation gte, and still
        // return a correctly-ranked page (capping the count must never
        // corrupt the page).
        let dir = std::env::temp_dir().join("kosha-test-or-cap");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_or_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        let mut capped_q = mk_query_or("solar lunar", 5);
        capped_q.total_hits_cap = Some(10);
        let capped = searcher.search(&ns, &manifest, &capped_q, None).unwrap();
        assert_eq!(capped.total_hits, 10);
        assert_eq!(capped.total_hits_relation, TotalHitsRelation::Gte);
        assert_eq!(capped.results.len(), 5);

        // The page itself must be untouched by capping — same top-5 as an
        // uncapped OR query over the identical corpus/terms.
        let uncapped = searcher
            .search(&ns, &manifest, &mk_query_or("solar lunar", 5), None)
            .unwrap();
        assert_eq!(page_ids(&capped), page_ids(&uncapped));
        for (c, u) in capped.results.iter().zip(uncapped.results.iter()) {
            assert!((c.score - u.score).abs() < 1e-9);
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn or_query_exact_total_hits_ignores_a_low_cap() {
        // `exact_total_hits: true` must force the full, exact union count
        // (300) even with a cap that would otherwise bind — proving the
        // WAND-skip fast path is bypassed entirely (see
        // `can_block_max_wand`'s operator/count_budget guard) rather than
        // just having its counter capped after the fact.
        let dir = std::env::temp_dir().join("kosha-test-or-exact-ignores-cap");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_or_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        let mut q = mk_query_or("solar lunar", 5);
        q.total_hits_cap = Some(10);
        q.exact_total_hits = Some(true);
        let r = searcher.search(&ns, &manifest, &q, None).unwrap();
        assert_eq!(r.total_hits, 300);
        assert_eq!(r.total_hits_relation, TotalHitsRelation::Eq);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn or_query_disjoint_terms_union_is_additive() {
        // Two terms that never co-occur: total_hits must equal the exact
        // sum of their document frequencies — no overcounting (each doc
        // still counted once) and no undercounting (dedup logic mustn't
        // mistake "different docs, same first cursor position" for a
        // shared match).
        let dir = std::env::temp_dir().join("kosha-test-or-disjoint-additive");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let n = 600;
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        let mut alpha_docs = 0usize;
        let mut beta_docs = 0usize;
        for i in 0..n {
            let mut content = String::new();
            if i % 3 == 0 {
                content.push_str("alphaterm ");
                alpha_docs += 1;
            } else if i % 5 == 0 {
                content.push_str("betaterm ");
                beta_docs += 1;
            } else {
                content.push_str("filler ");
            }
            content.push_str(&"pad ".repeat(i % 11));
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text("content", content)],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());

        let r = searcher
            .search(&ns, &manifest, &mk_query_or("alphaterm betaterm", 5), None)
            .unwrap();
        assert_eq!(r.total_hits, alpha_docs + beta_docs);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn multi_term_wand_matches_legacy_path_hits_ranking_and_scores() {
        // The leapfrog block-max AND join must be observably identical to
        // the general HashMap-intersection path it fast-paths: same
        // total_hits (exact — the KIZC lesson: a pruning path that bends
        // the count would look *better* while broken), same page order,
        // same scores.
        let dir = std::env::temp_dir().join("kosha-test-wand-parity");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let n = 600; // ≈400 "beta" postings → several 128-posting blocks
        let manifest = mk_wand_corpus(&dir, &ns.0, n);
        let searcher = Searcher::new(dir.clone());

        for query_text in ["alpha beta", "alpha beta gamma"] {
            let wand = searcher
                .search(&ns, &manifest, &mk_query(query_text, 10), None)
                .unwrap();
            let legacy = searcher
                .search(
                    &ns,
                    &manifest,
                    &force_legacy(mk_query(query_text, 10)),
                    None,
                )
                .unwrap();
            assert!(wand.total_hits > 0, "{query_text}: corpus must intersect");
            assert_eq!(
                wand.total_hits, legacy.total_hits,
                "{query_text}: pruned path must report the exact hit count"
            );
            assert_eq!(
                page_ids(&wand),
                page_ids(&legacy),
                "{query_text}: page ranking must match the legacy path"
            );
            for (w_doc, l_doc) in wand.results.iter().zip(legacy.results.iter()) {
                assert!(
                    (w_doc.score - l_doc.score).abs() < 1e-9,
                    "{query_text}: score mismatch on {}: {} vs {}",
                    w_doc.doc_id.0,
                    w_doc.score,
                    l_doc.score
                );
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    // ── Per-request BM25 parameters (issue #247) ────────────────────────

    fn with_bm25(mut q: SearchQuery, k1: f64, b: f64) -> SearchQuery {
        q.bm25_params = kosha_core::Bm25Overrides::new(k1, b);
        q
    }

    fn assert_same_page(label: &str, wand: &SearchResult, legacy: &SearchResult) {
        assert_eq!(
            wand.total_hits, legacy.total_hits,
            "{label}: pruned path must report the exact hit count"
        );
        assert_eq!(
            page_ids(wand),
            page_ids(legacy),
            "{label}: page ranking must match the exhaustive path"
        );
        for (w, l) in wand.results.iter().zip(legacy.results.iter()) {
            assert!(
                (w.score - l.score).abs() < 1e-9,
                "{label}: score mismatch on {}: {} vs {}",
                w.doc_id.0,
                w.score,
                l.score
            );
        }
    }

    #[test]
    fn bm25_b_zero_vs_one_changes_ranking_on_varied_lengths() {
        // One long doc that repeats the term, one short doc that says it
        // once. With b=0 length is ignored and the higher tf wins; with
        // b=1 the long doc is fully length-normalized and the short doc
        // wins. Before #247 both requests ranked identically because the
        // request's parameters never reached the scorer.
        let dir = std::env::temp_dir().join("kosha-test-bm25-b-ranking");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        w.add_document(
            DocumentId("long".into()),
            vec![Field::text(
                "content",
                format!("alpha alpha alpha{}", " filler".repeat(60)),
            )],
        );
        w.add_document(
            DocumentId("short".into()),
            vec![Field::text("content", "alpha")],
        );
        for i in 0..8 {
            w.add_document(
                DocumentId(format!("other-{i}")),
                vec![Field::text(
                    "content",
                    "unrelated words here ".repeat(i + 1),
                )],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 10,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let run = |b: f64| {
            searcher
                .search(
                    &ns,
                    &manifest,
                    &with_bm25(mk_query("alpha", 10), 1.2, b),
                    None,
                )
                .unwrap()
        };
        let b0 = run(0.0);
        let b1 = run(1.0);
        assert_eq!(page_ids(&b0), vec!["long", "short"], "b=0 ignores length");
        assert_eq!(page_ids(&b1), vec!["short", "long"], "b=1 penalizes length");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn bm25_b_changes_ranking_on_wand_corpus() {
        // Same property on the larger multi-block corpus the WAND tests
        // use, through the pruned single-term and AND paths.
        let dir = std::env::temp_dir().join("kosha-test-bm25-b-wand-corpus");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_wand_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());
        for text in ["alpha", "alpha beta"] {
            let b0 = searcher
                .search(
                    &ns,
                    &manifest,
                    &with_bm25(mk_query(text, 10), 1.2, 0.0),
                    None,
                )
                .unwrap();
            let b1 = searcher
                .search(
                    &ns,
                    &manifest,
                    &with_bm25(mk_query(text, 10), 1.2, 1.0),
                    None,
                )
                .unwrap();
            assert_ne!(page_ids(&b0), page_ids(&b1), "{text}: b must matter");
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Non-default parameter sets for the parity tests, including every
    /// boundary the validator accepts: k1=0 (tf saturates immediately,
    /// every match scores idf), b=0 (no length normalization) and b=1
    /// (full normalization).
    const BM25_PARAM_GRID: [(f64, f64); 6] = [
        (0.0, 0.0),
        (0.0, 1.0),
        (0.5, 0.3),
        (2.0, 0.0),
        (2.0, 1.0),
        (3.5, 0.9),
    ];

    #[test]
    fn wand_matches_exhaustive_path_under_non_default_bm25_params() {
        // The block-max ceilings are computed from stored max_tf /
        // min_field_length with the request's scorer, so pruning must stay
        // exact for any valid k1/b: single term, AND join, OR join, and a
        // deep page, each against the exhaustive (legacy) path.
        let dir = std::env::temp_dir().join("kosha-test-bm25-params-wand-parity");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let and_manifest = mk_wand_corpus(&dir.join("and"), &ns.0, 600);
        let or_manifest = mk_or_corpus(&dir.join("or"), &ns.0, 600);
        let and_searcher = Searcher::new(dir.join("and"));
        let or_searcher = Searcher::new(dir.join("or"));

        let default_alpha = and_searcher
            .search(&ns, &and_manifest, &mk_query("alpha", 10), None)
            .unwrap();
        for (k1, b) in BM25_PARAM_GRID {
            for text in ["alpha", "alpha beta", "alpha beta gamma"] {
                let label = format!("AND {text:?} k1={k1} b={b}");
                let q = with_bm25(mk_query(text, 10), k1, b);
                let wand = and_searcher.search(&ns, &and_manifest, &q, None).unwrap();
                let legacy = and_searcher
                    .search(&ns, &and_manifest, &force_legacy(q), None)
                    .unwrap();
                assert!(wand.total_hits > 0, "{label}: corpus must match");
                assert_same_page(&label, &wand, &legacy);
            }

            // Deep page: from=20 must equal the slice of one big page.
            let mut deep = with_bm25(mk_query("alpha beta", 10), k1, b);
            deep.from = 20;
            let deep = and_searcher
                .search(&ns, &and_manifest, &deep, None)
                .unwrap();
            let full = and_searcher
                .search(
                    &ns,
                    &and_manifest,
                    &force_legacy(with_bm25(mk_query("alpha beta", 30), k1, b)),
                    None,
                )
                .unwrap();
            assert_eq!(
                page_ids(&deep),
                page_ids(&full)[20..30].to_vec(),
                "deep page k1={k1} b={b}"
            );

            let label = format!("OR k1={k1} b={b}");
            let q = with_bm25(mk_query_or("solar lunar", 10), k1, b);
            let wand = or_searcher.search(&ns, &or_manifest, &q, None).unwrap();
            let legacy = or_searcher
                .search(&ns, &or_manifest, &force_legacy(q), None)
                .unwrap();
            assert_same_page(&label, &wand, &legacy);

            // Guard against a vacuous pass: the request params must
            // actually reach the scorer.
            let alpha = and_searcher
                .search(
                    &ns,
                    &and_manifest,
                    &with_bm25(mk_query("alpha", 10), k1, b),
                    None,
                )
                .unwrap();
            assert!(
                (alpha.results[0].score - default_alpha.results[0].score).abs() > 1e-9,
                "k1={k1} b={b} must change scores vs. the defaults"
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn omitted_bm25_params_fall_back_to_segment_build_params() {
        // A segment built with non-default k1/b (kosha-build-segments
        // --bm25-k1/--bm25-b) keeps scoring with them when the request
        // says nothing, and a request that sets only one parameter takes
        // the other from the segment.
        let dir = std::env::temp_dir().join("kosha-test-bm25-segment-fallback");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..50 {
            w.add_document(
                DocumentId(format!("doc-{i:02}")),
                vec![Field::text(
                    "content",
                    format!("{}{}", "alpha ".repeat(i % 4 + 1), "pad ".repeat(i % 9)),
                )],
            );
        }
        w.finalize(Bm25Params { k1: 2.0, b: 0.2 }).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 50,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        let scores = |q: SearchQuery| -> Vec<(String, f64)> {
            searcher
                .search(&ns, &manifest, &q, None)
                .unwrap()
                .results
                .into_iter()
                .map(|d| (d.doc_id.0, d.score))
                .collect()
        };
        let close = |a: &[(String, f64)], b: &[(String, f64)]| {
            a.len() == b.len()
                && a.iter()
                    .zip(b)
                    .all(|(x, y)| x.0 == y.0 && (x.1 - y.1).abs() < 1e-9)
        };
        let omitted = scores(mk_query("alpha", 20));
        let explicit_segment = scores(with_bm25(mk_query("alpha", 20), 2.0, 0.2));
        let explicit_default = scores(with_bm25(mk_query("alpha", 20), 1.2, 0.75));
        assert!(close(&omitted, &explicit_segment), "omitted → segment k1/b");
        assert!(
            !close(&omitted, &explicit_default),
            "not the global default"
        );

        let mut only_b = mk_query("alpha", 20);
        only_b.bm25_params.b = Some(1.0);
        assert!(
            close(
                &scores(only_b),
                &scores(with_bm25(mk_query("alpha", 20), 2.0, 1.0))
            ),
            "b alone overrides b; k1 comes from the segment"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn out_of_range_bm25_params_are_rejected() {
        let dir = std::env::temp_dir().join("kosha-test-bm25-validation");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_wand_corpus(&dir, &ns.0, 20);
        let searcher = Searcher::new(dir.clone());
        for (k1, b) in [
            (-0.1, 0.75),
            (f64::NAN, 0.75),
            (f64::INFINITY, 0.75),
            (1.2, -0.01),
            (1.2, 1.01),
            (1.2, f64::NAN),
        ] {
            let err = searcher
                .search(
                    &ns,
                    &manifest,
                    &with_bm25(mk_query("alpha", 5), k1, b),
                    None,
                )
                .unwrap_err();
            assert!(
                matches!(err, KoshaError::InvalidQuery(_)),
                "k1={k1} b={b}: expected InvalidQuery, got {err}"
            );
        }
        for (k1, b) in [(0.0, 0.0), (0.0, 1.0), (100.0, 0.5)] {
            searcher
                .search(
                    &ns,
                    &manifest,
                    &with_bm25(mk_query("alpha", 5), k1, b),
                    None,
                )
                .unwrap_or_else(|e| panic!("k1={k1} b={b} is valid: {e}"));
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn multi_term_wand_deep_page_matches_full_sort_slice() {
        // Same shape as `bounded_topk_selection_matches_full_sort_order`,
        // but through the multi-term join: a deep page (from=20) must equal
        // the corresponding slice of an unbounded query — proving the
        // per-segment top-`from + max_results` bound and the block pruning
        // don't starve deep pagination.
        let dir = std::env::temp_dir().join("kosha-test-wand-deep-page");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_wand_corpus(&dir, &ns.0, 600);
        let searcher = Searcher::new(dir.clone());

        // The reference slice comes from the LEGACY path (forced via the
        // gate-bypass cursor) — an unbounded WAND query would exercise the
        // same join being tested, and a systematic join bug shared by both
        // k values would cancel out and pass. (`from` is ignored under
        // search_after, so legacy can only supply the full sorted list,
        // which is exactly what slicing needs.)
        let full = searcher
            .search(
                &ns,
                &manifest,
                &force_legacy(mk_query("alpha beta", 600)),
                None,
            )
            .unwrap();
        let mut deep = mk_query("alpha beta", 5);
        deep.from = 20;
        let page = searcher.search(&ns, &manifest, &deep, None).unwrap();
        assert_eq!(page.total_hits, full.total_hits);
        assert_eq!(
            page_ids(&page),
            page_ids(&full)[20..25].to_vec(),
            "deep page must match the equivalent slice of a legacy full sort"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn corrupt_postings_fail_closed_not_truncated_or_inflated() {
        // On-disk corruption of a TOC-present term's blob must fail the
        // query LOUDLY: a hard error, never a truncated AND intersection,
        // never a total_hits claiming docs the page can't contain, never a
        // process abort from an unbounded allocation — and (now that the
        // blob-presence cache makes eviction races possible) never the old
        // silent term-drop either, which returned different results with
        // no signal anything was wrong. The server invalidates its
        // hydration/presence caches on this error and refetches on retry,
        // which repairs eviction; true corruption keeps erroring loudly —
        // the correct outcome for data needing repair. The corpus is small
        // enough that blobs stay under the KIZC compression threshold, so
        // the test can corrupt raw span bytes in place.
        let dir = std::env::temp_dir().join("kosha-test-corrupt-fail-closed");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        for i in 0..150 {
            let mut text = format!("alpha{}", " filler".repeat(i % 5));
            if i % 2 == 0 {
                text.push_str(" beta");
            }
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text("t", text)],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 150,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };

        // Baseline (uncorrupted): "alpha beta" intersects, "beta" matches.
        {
            let searcher = Searcher::new(dir.clone());
            let both = searcher
                .search(&ns, &manifest, &mk_query("alpha beta", 10), None)
                .unwrap();
            assert_eq!(both.total_hits, 75);
            let beta = searcher
                .search(&ns, &manifest, &mk_query("beta", 10), None)
                .unwrap();
            assert_eq!(beta.total_hits, 75);
        }

        // Corrupt beta's posting-blob shard on disk (garbage over the
        // middle third — hits the span regardless of internal layout).
        let blob_path = seg_dir.join(kosha_segment::posting_blob_file_for_term("beta"));
        let mut blob = std::fs::read(&blob_path).unwrap();
        let (start, end) = (blob.len() / 3, blob.len() * 2 / 3);
        for b in &mut blob[start..end] {
            *b = 0xFF;
        }
        std::fs::write(&blob_path, &blob).unwrap();

        // Fresh searcher — no cached postings from the baseline pass.
        let searcher = Searcher::new(dir.clone());
        let alpha_only = searcher
            .search(&ns, &manifest, &mk_query("alpha", 10), None)
            .unwrap();
        assert_eq!(alpha_only.total_hits, 150, "alpha's shard is untouched");

        let both = searcher.search(&ns, &manifest, &mk_query("alpha beta", 10), None);
        assert!(
            both.is_err(),
            "an unreadable blob for a TOC-present term must error, not \
             silently drop the term or truncate the intersection: {both:?}"
        );

        let beta = searcher.search(&ns, &manifest, &mk_query("beta", 10), None);
        assert!(
            beta.is_err(),
            "an undecodable single term must error, not report zero hits \
             or the span-header df: {beta:?}"
        );

        // An exact-count OR takes the general path's scoring-only walk
        // (no full decode): a corrupt block must still fail it, not drop
        // beta's documents from the union.
        let mut or = mk_query_or("alpha beta", 10);
        or.exact_total_hits = Some(true);
        let or = searcher.search(&ns, &manifest, &or, None);
        assert!(
            or.is_err(),
            "an unreadable OR term must error, not shrink the union: {or:?}"
        );

        // A term genuinely absent from the corpus is a normal non-match:
        // the footer's term bloom AND-prunes the segment to a clean zero —
        // crucially with no error, proving the failure flag distinguishes
        // "absent" from "unreadable".
        let absent = searcher
            .search(&ns, &manifest, &mk_query("alpha nosuchterm", 10), None)
            .unwrap();
        assert_eq!(
            absent.total_hits, 0,
            "bloom-pruned absent term is a clean zero"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn evicted_posting_blob_errors_instead_of_silent_absence() {
        // The blob-presence-cache eviction race, end to end: a blob file
        // DELETED after the segment was opened (what a disk-cache LRU
        // eviction looks like) must surface as a hard error the server can
        // react to (invalidate presence caches, rehydrate, retry) — never
        // as a silent zero-term result.
        let dir = std::env::temp_dir().join("kosha-test-evicted-blob");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir.clone());
        for i in 0..150 {
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text(
                    "t",
                    format!("alpha beta{}", " pad".repeat(i % 4)),
                )],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: 150,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());
        // Open + warm the segment so the reader is cached, THEN evict
        // beta's shard file from under it.
        let ok = searcher
            .search(&ns, &manifest, &mk_query("alpha", 10), None)
            .unwrap();
        assert_eq!(ok.total_hits, 150);
        std::fs::remove_file(seg_dir.join(kosha_segment::posting_blob_file_for_term("beta")))
            .unwrap();

        let r = searcher.search(&ns, &manifest, &mk_query("alpha beta", 10), None);
        assert!(
            r.is_err(),
            "evicted blob for a TOC-present term must error: {r:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn wand_page_matches_legacy_on_exact_score_ties() {
        // Score ties are where bounded top-k selection policies diverge:
        // the legacy path keeps every candidate and the global merge
        // breaks ties by doc_id ascending, so the WAND paths must apply
        // the same (score desc, doc_id asc) total order at insert time.
        // Every doc here has IDENTICAL text (same tf, same field length →
        // identical BM25 score), and doc_ids are assigned in REVERSE of
        // insertion order so "first k inserted" ≠ "k smallest doc_ids" —
        // a first-come tie policy fails this test, doc_id tiebreak passes.
        let dir = std::env::temp_dir().join("kosha-test-wand-tie-parity");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let n = 300;
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..n {
            w.add_document(
                DocumentId(format!("doc-{:04}", n - 1 - i)),
                vec![Field::text("content", "even filler filler")],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());

        // Single-term arm and multi-term join arm, both against legacy.
        for text in ["even", "even filler"] {
            let wand = searcher
                .search(&ns, &manifest, &mk_query(text, 10), None)
                .unwrap();
            let legacy = searcher
                .search(&ns, &manifest, &force_legacy(mk_query(text, 10)), None)
                .unwrap();
            assert_eq!(wand.total_hits, legacy.total_hits, "{text}: total_hits");
            assert_eq!(
                page_ids(&wand),
                page_ids(&legacy),
                "{text}: tied-score page must match legacy's doc_id tiebreak"
            );
            assert_eq!(
                page_ids(&wand),
                (0..10).map(|i| format!("doc-{i:04}")).collect::<Vec<_>>(),
                "{text}: ties must resolve to the lexicographically smallest doc_ids"
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn multi_term_wand_absent_term_requires_all_terms() {
        // Bloom pruning and exact TOC checks must agree: an AND query
        // with an absent required term is empty on both scoring paths.
        let dir = std::env::temp_dir().join("kosha-test-wand-absent-term");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let manifest = mk_wand_corpus(&dir, &ns.0, 200);
        let seg_dir = dir.join(&ns.0).join("s1");

        // Layer 1: bloom present → segment pruned, parity at zero.
        let searcher = Searcher::new(dir.clone());
        let wand = searcher
            .search(&ns, &manifest, &mk_query("alpha nosuchterm", 10), None)
            .unwrap();
        let legacy = searcher
            .search(
                &ns,
                &manifest,
                &force_legacy(mk_query("alpha nosuchterm", 10)),
                None,
            )
            .unwrap();
        assert_eq!(wand.total_hits, 0, "term bloom AND-prunes the segment");
        assert_eq!(legacy.total_hits, 0);

        // Without the bloom, the exact TOC check still rejects the segment.
        let mut footer = SegmentReader::read_footer(&seg_dir).unwrap();
        footer.term_bloom = None;
        std::fs::write(
            seg_dir.join("footer.json"),
            serde_json::to_string_pretty(&footer).unwrap(),
        )
        .unwrap();
        let searcher = Searcher::new(dir.clone());
        let wand = searcher
            .search(&ns, &manifest, &mk_query("alpha nosuchterm", 10), None)
            .unwrap();
        let legacy = searcher
            .search(
                &ns,
                &manifest,
                &force_legacy(mk_query("alpha nosuchterm", 10)),
                None,
            )
            .unwrap();
        assert_eq!(wand.total_hits, 0, "AND requires the absent term too");
        assert_eq!(wand.total_hits, legacy.total_hits);
        assert_eq!(page_ids(&wand), page_ids(&legacy));

        // All query terms absent → zero hits, no candidates, even without
        // the bloom to prune early.
        let none = searcher
            .search(
                &ns,
                &manifest,
                &mk_query("nosuchterm alsomissing", 10),
                None,
            )
            .unwrap();
        assert_eq!(none.total_hits, 0);
        assert!(none.results.is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn multi_term_wand_skewed_df_essential_term_drives_join() {
        // The shape the rarest-first alignment order is for: two
        // stopword-scale dense terms (~90%/~87% of docs) ANDed with one
        // genuinely rare term (3 postings, chosen so all 3 also carry both
        // dense terms — an exact, deterministic 3-doc intersection out of a
        // 2000-doc corpus). The join must still find exactly that
        // intersection when the rare term is probed first each pass —
        // this test only checks the *observable* result (parity with the
        // legacy path), not the internal probe order, since that ordering
        // is a perf detail, not a contract.
        let dir = std::env::temp_dir().join("kosha-test-wand-skewed-df");
        let _ = std::fs::remove_dir_all(&dir);
        let ns = NamespaceId("test".into());
        let n = 2000;
        let needle_docs = [5usize, 15, 25];
        let seg_dir = dir.join(&ns.0).join("s1");
        let mut w = SegmentWriter::new(SegmentId("s1".into()), seg_dir);
        for i in 0..n {
            let mut words = Vec::new();
            if i % 10 != 0 {
                words.push("common1".to_string());
            }
            if i % 8 != 0 {
                words.push("common2".to_string());
            }
            if needle_docs.contains(&i) {
                words.push("needle".to_string());
            }
            // Distinct padding length → distinct length norms → no score ties.
            words.extend(std::iter::repeat_n("pad".to_string(), i % 13));
            w.add_document(
                DocumentId(format!("doc-{i:04}")),
                vec![Field::text("content", words.join(" "))],
            );
        }
        w.finalize(Bm25Params::default()).unwrap();
        let manifest = Manifest {
            version: 1,
            segments: vec![ManifestEntry {
                segment_id: SegmentId("s1".into()),
                doc_count: n as u32,
            }],
            segment_footers: Default::default(),
            footer_crc32: Default::default(),
            wal_checkpoint: 0,
            wal_origin: None,
            tombstones: Default::default(),
            deletion_vectors: Default::default(),
            branch: None,
            schema: None,
            retired: Default::default(),
            shards: None,
        };
        let searcher = Searcher::new(dir.clone());

        for query_text in ["common1 needle", "common1 common2 needle"] {
            let wand = searcher
                .search(&ns, &manifest, &mk_query(query_text, 10), None)
                .unwrap();
            let legacy = searcher
                .search(
                    &ns,
                    &manifest,
                    &force_legacy(mk_query(query_text, 10)),
                    None,
                )
                .unwrap();
            assert_eq!(
                wand.total_hits,
                needle_docs.len(),
                "{query_text}: the rare term bounds the exact intersection size"
            );
            assert_eq!(wand.total_hits, legacy.total_hits, "{query_text}");
            assert_eq!(page_ids(&wand), page_ids(&legacy), "{query_text}");
            for (w_doc, l_doc) in wand.results.iter().zip(legacy.results.iter()) {
                assert!(
                    (w_doc.score - l_doc.score).abs() < 1e-9,
                    "{query_text}: score mismatch on {}: {} vs {}",
                    w_doc.doc_id.0,
                    w_doc.score,
                    l_doc.score
                );
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

